-- Data referensi Capaian Pembelajaran (CP) SD/MI, SMP/MTs, SMA/MA
-- Sumber: Keputusan Kepala BSKAP Kemendikdasmen Nomor 046/H/KR/2025 tentang Capaian Pembelajaran pada PAUD, Jenjang Pendidikan Dasar, dan Jenjang Pendidikan Menengah
-- Lampiran II — CP untuk SD/MI, SMP/MTs, dan SMA/MA; ditetapkan 2025-07-16; diekstrak 2026-10-24.
-- 46 mapel, 532 baris CP (per mapel x fase x elemen), 1071 butir CP.
-- Tabel ref_cp_butir adalah pecahan kalimat CP (dipisah titik koma/kalimat) sebagai bahan menyusun TP;
-- ini BUKAN tujuan pembelajaran resmi. TP tetap disusun guru/satuan pendidikan.

begin;

create table if not exists public.ref_mapel (
  id text primary key,
  nama text not null,
  singkatan text not null,
  urutan int not null,
  fase text not null,          -- fase yang memiliki CP, mis. 'ABCDEF'
  jenjang text not null
);

create table if not exists public.ref_cp (
  id text primary key,         -- mis. 'ipa-d-1'
  mapel_id text not null references public.ref_mapel(id),
  fase char(1) not null check (fase in ('A','B','C','D','E','F')),
  jenjang text not null,
  kelas text not null,
  urutan int not null,
  elemen text not null,
  capaian text not null,
  elemen_sumber text not null,
  halaman_pdf int,
  catatan text
);
create index if not exists ref_cp_mapel_fase on public.ref_cp (mapel_id, fase);

create table if not exists public.ref_cp_butir (
  id text primary key,         -- mis. 'ipa-d-1-3'
  cp_id text not null references public.ref_cp(id) on delete cascade,
  urutan int not null,
  sub_elemen text,
  butir text not null,
  kata_kerja text
);
create index if not exists ref_cp_butir_cp on public.ref_cp_butir (cp_id);

-- Referensi hanya-baca untuk pengguna yang sudah masuk
alter table public.ref_mapel enable row level security;
alter table public.ref_cp enable row level security;
alter table public.ref_cp_butir enable row level security;
drop policy if exists "ref_mapel dibaca pengguna" on public.ref_mapel;
drop policy if exists "ref_cp dibaca pengguna" on public.ref_cp;
drop policy if exists "ref_cp_butir dibaca pengguna" on public.ref_cp_butir;
create policy "ref_mapel dibaca pengguna" on public.ref_mapel for select to authenticated using (true);
create policy "ref_cp dibaca pengguna" on public.ref_cp for select to authenticated using (true);
create policy "ref_cp_butir dibaca pengguna" on public.ref_cp_butir for select to authenticated using (true);

on conflict (id) do update set nama = excluded.nama, singkatan = excluded.singkatan, urutan = excluded.urutan, fase = excluded.fase, jenjang = excluded.jenjang;

• Allah Pemelihara: Memahami pemeliharaan Allah pada dirinya melalui kehadiran keluarga.
• Allah Penyelamat -
• Allah Pembaru', 'Elemen Allah Berkarya', 34, null),
  ('pak-a-2', 'pak', 'A', 'SD/MI', 'I–II', 2, 'Manusia dan Nilai-Nilai Kristiani', '• Hakikat Manusia: Memahami diri sebagai pribadi yang bertumbuh dan berkembang.
• Nilai-nilai Kristiani: Memahami makna kebaikan, ramah dan sopan di rumah dan di sekolah.', 'Elemen Manusia dan Nilai- nilai Kristiani', 35, null),
  ('pak-a-3', 'pak', 'A', 'SD/MI', 'I–II', 3, 'Gereja dan Masyarakat Majemuk', '• Tugas Panggilan Gereja: Memahami keberadaan gereja sebagai wadah berkumpul dan beribadah serta kewajiban berdoa dan memuji Tuhan.
• Masyarakat Majemuk: Memahami keragaman suku bangsa sebagai anugerah Allah.', 'Elemen Gereja dan Masyarakat Majemuk', 35, null),
  ('pak-a-4', 'pak', 'A', 'SD/MI', 'I–II', 4, 'Alam dan Lingkungan Hidup', '• Alam Ciptaan Allah: Memahami alam dan lingkungan hidup sebagai ciptaan Allah.
• Tanggung Jawab Manusia: Terhadap Alam Memahami tugas memelihara alam dan lingkungan hidup di rumah dan di sekolah.', 'Elemen Alam dan Lingkungan Hidup', 35, null),
  ('pak-b-1', 'pak', 'B', 'SD/MI', 'III–IV', 1, 'Allah Berkarya', '• Allah Pencipta: Memahami Allah menciptakan flora dan fauna, serta manusia (perempuan dan laki-laki).
• Allah Pemelihara: Memahami pemeliharaan Allah pada dirinya dan melalui kehadiran orang- orang di sekitarnya.
• Allah Penyelamat: Memahami Allah sebagai penyelamat.
• Allah Pembaru: Mengenal Allah pembaru', 'Elemen Allah Berkarya', 36, null),
  ('pak-b-2', 'pak', 'B', 'SD/MI', 'III–IV', 2, 'Manusia dan Nilai-Nilai Kristiani', '• Hakikat Manusia: Memahami diri sebagai makhluk individu dan sosial yang dapat bergaul dan bekerja sama dengan teman, saudara, dan orang tua.
• Nilai-nilai Kristiani: Memahami sikap disiplin di rumah dan di sekolah.', 'Elemen Manusia dan Nilai- nilai Kristiani', 36, null),
  ('pak-b-3', 'pak', 'B', 'SD/MI', 'III–IV', 3, 'Gereja dan Masyarakat Majemuk', '• Tugas Panggilan Gereja: Memahami tugas panggilan gereja untuk bersekutu, bersaksi, dan melayani.
• Masyarakat Majemuk: Memahami keragaman budaya dan agama sebagai anugerah Allah.', 'Elemen Gereja dan Masyarakat Majemuk', 36, null),
  ('pak-b-4', 'pak', 'B', 'SD/MI', 'III–IV', 4, 'Alam dan Lingkungan Hidup', '• Alam Ciptaan Allah: Memahami Allah hadir dalam berbagai fenomena alam.
• Tanggung Jawab Manusia: Terhadap Alam Memahami upaya memelihara alam dan lingkungan sekitarnya.', 'Elemen Alam dan Lingkungan Hidup', 36, null),
  ('pak-c-1', 'pak', 'C', 'SD/MI', 'V–VI', 1, 'Allah Berkarya', '• Allah Pencipta: Memahami Allah Pencipta berkarya melalui keluarga, sekolah, dan masyarakat.
• Allah Pemelihara: Memahami Allah memelihara seluruh umat manusia termasuk mereka yang berkebutuhan khusus.
• Allah Penyelamat: Memahami Allah menyelamatkan manusia melalui Yesus Kristus.
• Allah Pembaru: Memahami Allah membarui hidup Manusia.', 'Elemen Allah Berkarya', 37, null),
  ('pak-c-2', 'pak', 'C', 'SD/MI', 'V–VI', 2, 'Manusia dan Nilai-Nilai Kristiani', '• Hakikat Manusia: Memahami bahwa manusia adalah makhluk terbatas.
• Nilai-nilai Kristiani: Memahami buah Roh dalam interaksi antarsesama.', 'Elemen Manusia dan Nilai- nilai Kristiani', 37, null),
  ('pak-c-3', 'pak', 'C', 'SD/MI', 'V–VI', 3, 'Gereja dan Masyarakat Majemuk', '• Tugas Panggilan Gereja: Memahami pelayanan terhadap sesama sebagai tanggung jawab orang beriman dalam kehidupan.
• Masyarakat Majemuk: Memahami hidup rukun dan toleransi dalam masyarakat majemuk.', 'Elemen Gereja dan Masyarakat Majemuk', 37, null),
  ('pak-c-4', 'pak', 'C', 'SD/MI', 'V–VI', 4, 'Alam dan Lingkungan Hidup', '• Alam Ciptaan Allah: Memahami Allah hadir melalui alam ciptaan.
• Tanggung Jawab Manusia: Terhadap Alam Memahami tanggung jawab orang beriman dalam memelihara alam dan lingkungan hidup.', 'Elemen Alam dan Lingkungan Hidup', 37, null),
  ('pak-d-1', 'pak', 'D', 'SMP/MTs', 'VII–IX', 1, 'Allah Berkarya', '• Allah Pencipta: Memahami karya Allah dalam hidup manusia yang mengubah masa depan manusia dan dunia, karya Allah melalui berbagai perubahan yang dihadirkan gereja, perkembangan iptek, dan memanfaatkan iptek secara bertanggung jawab.
• Allah Pemelihara: Memahami Allah memelihara seluruh ciptaan-Nya dan kehidupan manusia yang dinamis ada dalam pemeliharaan-Nya, dan pemeliharaan Allah memberi inspirasi dalam kehidupan.
• Allah Penyelamat: Memahami teladan Yesus Kristus dalam hidup beriman.
• Allah Pembaru: Memahami karya Roh Kudus memimpin hidup orang beriman dalam menghadapi berbagai tantangan.', 'Elemen Allah Berkarya', 38, null),
  ('pak-d-2', 'pak', 'D', 'SMP/MTs', 'VII–IX', 2, 'Manusia dan Nilai-Nilai Kristiani', '• Hakikat Manusia: Memahami pergaulan remaja masa kini dan menjalaninya dengan meneladani hidup Yesus Kristus.
• Nilai-Nilai Kristiani: Memahami prinsip rendah hati, penguasaan diri, dan peduli terhadap sesama, makna persahabatan dalam kehidupan sehari-hari.', 'Elemen Manusia dan Nilai- nilai Kristiani', 39, null),
  ('pak-d-3', 'pak', 'D', 'SMP/MTs', 'VII–IX', 3, 'Gereja dan Masyarakat Majemuk', '• Tugas Panggilan Gereja: Memahami makna kehadiran gereja dalam pelayanan yang membawa pembaruan bagi dunia secara keseluruhan.
• Masyarakat Majemuk: Memahami model dialog dan kerjasama antarumat beragama dalam rangka penguatan moderasi beragama.', 'Elemen Gereja dan Masyarakat Majemuk', 39, null),
  ('pak-d-4', 'pak', 'D', 'SMP/MTs', 'VII–IX', 4, 'Alam dan Lingkungan Hidup', '• Alam Ciptaan Allah: Memahami bahwa pemeliharaan Allah terus berlangsung terhadap alam dan manusia di segala situasi.
• Tanggung Jawab Manusia: Terhadap Alam Memahami bahwa manusia diberi tugas oleh Allah untuk mengolah serta memelihara alam dan lingkungan hidup.', 'Elemen Alam dan Lingkungan Hidup', 39, null),
  ('pak-e-1', 'pak', 'E', 'SMA/MA', 'X', 1, 'Allah Berkarya', '• Allah Pencipta: Memahami manusia diberi kemampuan untuk mengembangkan rasio dan kepekaan hati nurani.
• Allah Pemelihara: Memahami bentuk-bentuk pemeliharaan Allah dalam setiap situasi kehidupan.
• Allah Penyelamat: Memahami karya penyelamatan Allah melalui peran keluarga dan orang tua sebagai pendidik pertama dan utama.
• Allah Pembaru: Memahami bahwa Roh Kudus membarui dan memulihkan kehidupan keluarga.', 'Elemen Allah Berkarya', 40, null),
  ('pak-e-2', 'pak', 'E', 'SMA/MA', 'X', 2, 'Manusia dan Nilai-Nilai Kristiani', '• Hakikat Manusia: Memahami peran dirinya sebagai remaja Kristen mengacu pada teks Alkitab dan tokoh-tokoh inspiratif.
• Nilai-Nilai Kristiani: Memahami prinsip kesetiaan, kasih dan keadilan dalam kehidupan sosial yang lebih luas.', 'Elemen Manusia dan Nilai- Nilai Kristiani', 40, null),
  ('pak-e-3', 'pak', 'E', 'SMA/MA', 'X', 3, 'Gereja dan Masyarakat Majemuk', '• Tugas Panggilan Gereja: Memahami peran gereja dalam mewujudkan solidaritas dan kebersamaan dalam hubungan antarumat beragama dan internal umat beragama terkait dengan isu ras, etnis, serta gender di dalam masyarakat.
• Masyarakat Majemuk: Memahami peran keluarga dan sekolah sebagai lembaga pendidikan yang mendidik kemajemukan.', 'Elemen Gereja dan Masyarakat Majemuk', 40, null),
  ('pak-e-4', 'pak', 'E', 'SMA/MA', 'X', 4, 'Alam dan Lingkungan Hidup', '• Alam Ciptaan Allah: Memahami berbagai fakta kerusakan alam dan perubahan iklim serta pemanasan global yang mengancam hidup manusia dan alam.
• Tanggung Jawab Manusia: Terhadap Alam Memahami berbagai bentuk pencegahan dan pelestarian alam demi keberlanjutan hidup manusia dan alam.', 'Elemen Alam dan Lingkungan Hidup', 41, null),
  ('pak-f-1', 'pak', 'F', 'SMA/MA', 'XI–XII', 1, 'Allah Berkarya', '• Allah Pencipta: Memahami perkembangan kebudayaan, ilmu pengetahuan dan teknologi, serta demokrasi dan HAM sebagai anugerah Allah yang dijabarkan dalam praktik hidup sehari-hari.
• Allah Pemelihara: Memahami talenta pemberian Allah serta menggunakannya untuk kepentingan gereja, bangsa, dan negara.
• Allah Penyelamat: Memahami karya penyelamatan Allah melalui peran masyarakat dan bangsa untuk mewujudkan nilai-nilai demokrasi dan HAM.
• Allah Pembaru: Memahami bahwa Roh Kudus membarui dan memulihkan kehidupan gereja, bangsa, dan negara.', 'Elemen Allah Berkarya', 41, null),
  ('pak-f-2', 'pak', 'F', 'SMA/MA', 'XI–XII', 2, 'Manusia dan Nilai-Nilai Kristiani', '• Hakikat Manusia: Memahami pertumbuhan diri dan tanggung jawab sebagai pribadi dewasa serta keadilan sebagai dasar demokrasi dan HAM.
• Nilai-nilai Kristiani: Memahami prinsip damai sejahtera sebagai landasan hidup berkeluarga dan bermasyarakat.', 'Elemen Manusia dan Nilai- nilai Kristiani', 42, null),
  ('pak-f-3', 'pak', 'F', 'SMA/MA', 'XI–XII', 3, 'Gereja dan Masyarakat Majemuk', '• Tugas Panggilan Gereja: Memahami keteladanan tokoh-tokoh agama yang mengabdikan hidupnya bagi persaudaraan dan solidaritas serta isu-isu ras, etnis, kesetaraan gender dalam rangka mewujudkan keadilan.
• Masyarakat Majemuk: Memahami transformasi sosial pada lingkup masyarakat majemuk dalam rangka penguatan moderasi beragama.', 'Elemen Gereja dan Masyarakat Majemuk', 42, null),
  ('pak-f-4', 'pak', 'F', 'SMA/MA', 'XI–XII', 4, 'Alam dan Lingkungan Hidup', '• Alam Ciptaan Allah: Memahami prinsip pemeliharaan dan pelestarian alam serta keutuhan ciptaan Allah.
• Tanggung Jawab Manusia: Terhadap Alam Memahami sikap ugahari serta bijak dan adil dalam memanfaatkan dan melestarikan sumber daya alam demi kelestarian alam.', 'Elemen Alam dan Lingkungan Hidup', 42, null),
  ('pakat-a-1', 'pakat', 'A', 'SD/MI', 'I–II', 1, 'Pribadi Peserta Didik', 'Memahami dirinya sebagai pribadi yang dicintai Tuhan, memiliki anggota tubuh yang berguna, memahami cara merawat tubuhnya; memahami teman-teman, lingkungan rumah dan satuan pendidikan sebagai tempat mengembangkan potensi diri.', 'Pribadi Peserta Didik', 46, null),
  ('pakat-a-2', 'pakat', 'A', 'SD/MI', 'I–II', 2, 'Yesus Kristus', 'Memahami bahwa Tuhan menciptakan langit, bumi, dan seluruh isinya; memahami tokoh-tokoh iman di dalam Perjanjian Lama (Nuh, Abraham, Ishak, dan Yakub); memahami kisah kelahiran Tuhan Yesus, kisah tiga orang Majus, masa kanak-kanak Yesus di Nazaret, Yesus dipersembahkan di Bait Allah, dan berada di Bait Allah pada umur 12 tahun.', 'Yesus Kristus', 46, null),
  ('pakat-a-3', 'pakat', 'A', 'SD/MI', 'I–II', 3, 'Gereja', 'Memahami imannya dengan cara membuat tanda salib, berdoa Bapa Kami, Salam Maria, dan Kemuliaan; memahami iman dengan melaksanakan perintah Allah, dan membiasakan diri dengan berdoa pujian, syukur dan permohonan.', 'Gereja', 46, null),
  ('pakat-a-4', 'pakat', 'A', 'SD/MI', 'I–II', 4, 'Masyarakat', 'Memahami lingkungan keluarga, dan teman-teman, memiliki kebiasaan bekerja sama dengan anggota keluarga dan teman-teman; memahami iman di tengah masyarakat melalui kebiasaan hidup rukun dengan tetangga dan bergotong royong merawat lingkungan.', 'Masyarakat', 47, null),
  ('pakat-b-1', 'pakat', 'B', 'SD/MI', 'III–IV', 1, 'Pribadi Peserta Didik', 'Memahami dirinya sebagai pribadi yang tumbuh dan berkembang, mewujudkan iman dengan cara melakukan perbuatan baik; memahami diri sebagai pribadi yang unik, bersyukur dan bersedia mengembangkan keunikan diri bersama orang lain dan lingkungan sekitar.', 'Pribadi Peserta Didik', 47, null),
  ('pakat-b-2', 'pakat', 'B', 'SD/MI', 'III–IV', 2, 'Yesus Kristus', 'Memahami karya keselamatan Allah melalui tokoh-tokoh Yusuf, Musa, dan Yosua; memahami Sepuluh Perintah Allah sebagai pedoman hidup; memahami bangsa Israel memasuki tanah terjanji, Allah memberkati pemimpin Israel (Samuel, Saul, dan Daud); memahami Yesus sebagai pemenuhan janji Allah yang mewartakan Kerajaan Allah melalui perkataan, perbuatan, dan mukjizat', 'Yesus Kristus', 47, null),
  ('pakat-b-3', 'pakat', 'B', 'SD/MI', 'III–IV', 3, 'Gereja', 'Murid memahami sakramen baptis, sakramen ekaristi, dan sakramen tobat; mengungkapkan rasa syukur dalam doa pribadi dan doa bersama, mewujudkan makna doa melalui sikap dan tindakan dalam kehidupan sehari-hari.', 'Gereja', 47, null),
  ('pakat-b-4', 'pakat', 'B', 'SD/MI', 'III–IV', 4, 'Masyarakat', 'Mewujudkan imannya di tengah masyarakat melalui kebiasaan menghormati pemimpin masyarakat, menghargai tradisi masyarakat, melestarikan lingkungan alam; mewujudkan rasa hormat terhadap orang tua, menghormati hidup pribadi, menghormati milik orang lain.', 'Masyarakat', 48, null),
  ('pakat-c-1', 'pakat', 'C', 'SD/MI', 'V–VI', 1, 'Pribadi Peserta Didik', 'Memahami diri sebagai perempuan atau laki-laki sebagai citra Allah yang sederajat dan saling melengkapi; memahami hak dan kewajiban dirinya sebagai warga negara dan bangga sebagai bangsa Indonesia; memahami diri sebagai warga dunia.', 'Pribadi Peserta Didik', 48, null),
  ('pakat-c-2', 'pakat', 'C', 'SD/MI', 'V–VI', 2, 'Yesus Kristus', 'Memahami perjuangan tokoh-tokoh kitab suci: Daud sebagai pemimpin yang tangguh; Salomo yang bijaksana, dan Ester perempuan pemberani, serta tokoh Maria dan Elisabet yang setia dan berserah kepada Allah; meneladani Yesus yang taat kepada Allah; mengajarkan pengampunan, memanggil orang berdosa; menderita, wafat, dan bangkit; mengutus Roh Kudus untuk menguatkan para rasul, dan orang yang beriman kepada-Nya; memahami perjuangan Nabi Elia yang menobatkan bangsa Israel; Nabi Amos sebagai pejuang keadilan; dan Nabi Yesaya yang me-nubuat-kan kedatangan Juru Selamat; memahami Yesus yang mewartakan kerajaan Allah dengan perkataan dan perbuatan.', 'Yesus Kristus', 48, null),
  ('pakat-c-3', 'pakat', 'C', 'SD/MI', 'V–VI', 3, 'Gereja', 'Mewujudkan iman dalam kehidupan sehari-hari, melibatkan diri dalam kehidupan menggereja, sebagai wujud kehidupan bersama yang dijiwai oleh Roh Kudus; memahami gereja yang satu, kudus, katolik, dan apostolik; persekutuan para kudus; pengampunan dosa, kebangkitan badan dan kehidupan kekal.', 'Gereja', 49, null),
  ('pakat-c-4', 'pakat', 'C', 'SD/MI', 'V–VI', 4, 'Masyarakat', 'Memahami pentingnya terlibat aktif dalam pelestarian lingkungan, bersikap jujur, bertindak menurut hati nurani, menegakkan keadilan dalam hidup sehari-hari sebagai orang beriman kristiani, melakukan dialog antar umat beragama.', 'Masyarakat', 49, null),
  ('pakat-d-1', 'pakat', 'D', 'SMP/MTs', 'VII–IX', 1, 'Pribadi Peserta Didik', 'Memahami manusia sebagai citra Allah yang unik, sebagai laki-laki dan perempuan; memahami kemampuan dan keterbatasan; memahami diri yang tumbuh dan berkembang karena peran keluarga, teman, satuan pendidikan, dan gereja.', 'Pribadi Peserta Didik', 49, null),
  ('pakat-d-2', 'pakat', 'D', 'SMP/MTs', 'VII–IX', 2, 'Yesus Kristus', 'Memahami pribadi Yesus yang berbelas kasih, pengampun, dan pendoa; memahami pribadi dan karya Yesus sebagai pemenuhan janji Allah, yang mewartakan kerajaan Allah melalui sabda, perbuatan, dan mukjizat-Nya; memahami Yesus yang memanggil dan mengutus para murid-Nya; memahami sengsara, wafat, dan kebangkitan Yesus, peristiwa Yesus naik ke surga; memahami Yesus yang mengutus Roh Kudus, Roh Kudus memberi kekuatan bagi para murid dan umat manusia.', 'Yesus Kristus', 49, null),
  ('pakat-d-3', 'pakat', 'D', 'SMP/MTs', 'VII–IX', 3, 'Gereja', 'Memahami gereja sebagai komunitas, karya pelayanan (Kerygma, Liturgia, Martyria, Koinonia, dan Diakonia), gereja sebagai sakramen; memahami sakramen-sakramen inisiasi yaitu baptis, ekaristi, dan krisma; memahami sakramen tobat dan sakramen pengurapan orang sakit; memahami makna sakramen perkawinan, sakramen imamat dalam membangun masa depan.', 'Gereja', 50, null),
  ('pakat-d-4', 'pakat', 'D', 'SMP/MTs', 'VII–IX', 4, 'Masyarakat', 'Memahami kebebasan sebagai anak-anak Allah dan sabda bahagia dalam upaya membangun kehidupan bersama; memahami Allah sebagai sumber keselamatan sejati dan menanggapinya dengan beriman, hidup dalam kebersamaan dengan jemaat serta mengikuti teladan Bunda Maria; memahami hak dan kewajiban anggota gereja dan masyarakat; memahami pentingnya menghargai keluhuran martabat manusia dengan mengembangkan budaya kehidupan, keadilan dan kejujuran; memahami alam sebagai rumah kita bersama (Ensiklik Laudato Si); memahami sikap gereja Katolik terhadap agama dan kepercayaan lain (Nostra Aetate), membangun kebersamaan dengan semua orang.', 'Masyarakat', 50, null),
  ('pakat-e-1', 'pakat', 'E', 'SMA/MA', 'X', 1, 'Pribadi Peserta Didik', 'Memahami dirinya sebagai pribadi yang unik, kesetaraan antara laki-laki dan perempuan, memiliki keutuhan martabat sebagai citra Allah; memahami suara hati, mampu bersikap kritis dan bertanggung jawab terhadap pengaruh media massa, media sosial, ideologi, dan gaya hidup saat ini.', 'Pribadi Peserta Didik', 50, null),
  ('pakat-e-2', 'pakat', 'E', 'SMA/MA', 'X', 2, 'Yesus Kristus', 'Memahami Yesus sebagai Putra Allah dan Juru Selamat yang mewartakan kerajaan Allah, mengalami sengsara, wafat, bangkit, dan naik ke surga; memahami Tri Tunggal Maha Kudus, peran Roh Kudus; menjadikan Yesus sebagai idola dan sahabat sejati.', 'Yesus Kristus', 51, null),
  ('pakat-e-3', 'pakat', 'E', 'SMA/MA', 'X', 3, 'Gereja', 'Memahami kitab suci, radisi suci dan magisterium sebagai sumber ajaran kristiani.', 'Gereja', 51, null),
  ('pakat-e-4', 'pakat', 'E', 'SMA/MA', 'X', 4, 'Masyarakat', 'Memahami hidup berpola pada pribadi Yesus Kristus dalam mewujudkan imannya di tengah masyarakat.', 'Masyarakat', 51, null),
  ('pakat-f-1', 'pakat', 'F', 'SMA/MA', 'XI–XII', 1, 'Pribadi Peserta Didik', 'Memahami makna panggilan hidup berkeluarga,membiara, klerus, karya/profesi.', 'Pribadi Peserta Didik', 51, null),
  ('pakat-f-2', 'pakat', 'F', 'SMA/MA', 'XI–XII', 2, 'Yesus Kristus', '', 'Yesus Kristus', 51, 'Di dokumen sumber elemen ini bertanda "-" (tidak ada capaian tertulis untuk fase ini).'),
  ('pakat-f-3', 'pakat', 'F', 'SMA/MA', 'XI–XII', 3, 'Gereja', 'Memahami gereja sebagai umat Allah; memahami sifat gereja; memahami peran hierarki dan awam; memahami karya pastoral gereja (Kerygma, Koinonia, Liturgia, Diakonia, Martyria).', 'Gereja', 51, null),
  ('pakat-f-4', 'pakat', 'F', 'SMA/MA', 'XI–XII', 4, 'Masyarakat', 'Memahami hubungan gereja dan dunia, ajaran sosial gereja, hak asasi manusia dalam terang kitab suci; memahami budaya kasih, menghargai hidup; memahami makna kejujuran, keadilan, kebenaran, dan pelestarian lingkungan hidup; memahami keberagaman masyarakat Indonesia, moderasi beragama dalam konteks dialog dan kerja sama; memahami peran umat Katolik dalam membangun bangsa dan negara.', 'Masyarakat', 51, null),
  ('pah-a-1', 'pah', 'A', 'SD/MI', 'I–II', 1, 'Kitab Suci Weda', 'Memahami kitab Ramayana dan Mahabharata.', 'Kitab Suci Weda', 56, null),
  ('pah-a-2', 'pah', 'A', 'SD/MI', 'I–II', 2, 'Sraddha dan Bhakti', 'Memahami Hyang Widhi Wasa sebagai pencipta dan sumber hidup.', 'Sraddha dan Bhakti', 56, null),
  ('pah-a-3', 'pah', 'A', 'SD/MI', 'I–II', 3, 'Susila', 'Memahami Subha dan Asubha Karma, serta Tri Kaya Parisudha.', 'Susila', 56, null),
  ('pah-a-4', 'pah', 'A', 'SD/MI', 'I–II', 4, 'Acara', 'Memahami Dainika Upasana dan sarana persembahyangan.', 'Acara', 56, null),
  ('pah-a-5', 'pah', 'A', 'SD/MI', 'I–II', 5, 'Sejarah Agama Hindu', 'Memahami tokoh-tokoh kerajaan Hindu di Indonesia.', 'Sejarah Agama Hindu', 56, null),
  ('pah-b-1', 'pah', 'B', 'SD/MI', 'III–IV', 1, 'Kitab Suci Weda', 'Memahami kitab Purana.', 'Kitab Suci Weda', 56, null),
  ('pah-b-2', 'pah', 'B', 'SD/MI', 'III–IV', 2, 'Sraddha dan Bhakti', 'Memahami Hyang Widhi Wasa sebagai Tri Murti dan Cadu Sakti.', 'Sraddha dan Bhakti', 56, null),
  ('pah-b-3', 'pah', 'B', 'SD/MI', 'III–IV', 3, 'Susila', 'Memahami Tri Parartha dan Catur Paramitha.', 'Susila', 56, null),
  ('pah-b-4', 'pah', 'B', 'SD/MI', 'III–IV', 4, 'Acara', 'Memahami Hari Suci dan Tempat Suci agama Hindu sesuai kearifan lokal.', 'Acara', 57, null),
  ('pah-b-5', 'pah', 'B', 'SD/MI', 'III–IV', 5, 'Sejarah Agama Hindu', 'Memahami tokoh-tokoh kerajaan Hindu di Indonesia.', 'Sejarah Agama Hindu', 57, null),
  ('pah-c-1', 'pah', 'C', 'SD/MI', 'V–VI', 1, 'Kitab Suci Weda', 'Memahami Weda Sruti dan Weda Smerti.', 'Kitab Suci Weda', 57, null),
  ('pah-c-2', 'pah', 'C', 'SD/MI', 'V–VI', 2, 'Sraddha dan Bhakti', 'Memahami Bhuana Agung dan Bhuana Alit.', 'Sraddha dan Bhakti', 57, null),
  ('pah-c-3', 'pah', 'C', 'SD/MI', 'V–VI', 3, 'Susila', 'Memahami ajaran Catur Guru dan Catur Asrama.', 'Susila', 57, null),
  ('pah-c-4', 'pah', 'C', 'SD/MI', 'V–VI', 4, 'Acara', 'Memahami Panca Yadnya dan Manggalaning Yadnya.', 'Acara', 57, null),
  ('pah-c-5', 'pah', 'C', 'SD/MI', 'V–VI', 5, 'Sejarah Agama Hindu', 'Memahami Sejarah Perkembangan Agama Hindu di Indonesia.', 'Sejarah Agama Hindu', 57, null),
  ('pah-d-1', 'pah', 'D', 'SMP/MTs', 'VII–IX', 1, 'Kitab Suci Weda', 'Memahami Upaweda, Wedangga, dan Nibhanda.', 'Kitab Suci Weda', 57, null),
  ('pah-d-2', 'pah', 'D', 'SMP/MTs', 'VII–IX', 2, 'Sraddha dan Bhakti', 'Memahami Atman, Asta Aiswarya, dan Catur Marga.', 'Sraddha dan Bhakti', 57, null),
  ('pah-d-3', 'pah', 'D', 'SMP/MTs', 'VII–IX', 3, 'Susila', 'Memahami Tri Hita Karana, Catur Purusa Artha, serta Panca Yama Brata dan Panca Niyama Brata.', 'Susila', 57, null),
  ('pah-d-4', 'pah', 'D', 'SMP/MTs', 'VII–IX', 4, 'Acara', 'Memahami Upakara, Dharma Gita, serta Budaya Hidup Bersih dan Sehat menurut Weda.', 'Acara', 58, null),
  ('pah-d-5', 'pah', 'D', 'SMP/MTs', 'VII–IX', 5, 'Sejarah Agama Hindu', 'Memahami Sejarah Perkembangan Agama Hindu di Asia.', 'Sejarah Agama Hindu', 58, null),
  ('pah-e-1', 'pah', 'E', 'SMA/MA', 'X', 1, 'Kitab Suci Weda', 'Memahami Dharmasastra.', 'Kitab Suci Weda', 58, null),
  ('pah-e-2', 'pah', 'E', 'SMA/MA', 'X', 2, 'Sraddha dan Bhakti', 'Memahami Karmaphala dan Punarbhawa.', 'Sraddha dan Bhakti', 58, null),
  ('pah-e-3', 'pah', 'E', 'SMA/MA', 'X', 3, 'Susila', 'Memahami ajaran Catur Warna.', 'Susila', 58, null),
  ('pah-e-4', 'pah', 'E', 'SMA/MA', 'X', 4, 'Acara', 'Memahami Yadnya dan Ramayana dan Mahabhrata.', 'Acara', 58, null),
  ('pah-e-5', 'pah', 'E', 'SMA/MA', 'X', 5, 'Sejarah Agama Hindu', 'Memahami Corak Keagamaan Hindu di dunia.', 'Sejarah Agama Hindu', 58, null),
  ('pah-f-1', 'pah', 'F', 'SMA/MA', 'XI–XII', 1, 'Kitab Suci Weda', 'Memahami Kodifikasi Weda dan Ajaran Upanisad.', 'Kitab Suci Weda', 58, null),
  ('pah-f-2', 'pah', 'F', 'SMA/MA', 'XI–XII', 2, 'Sraddha dan Bhakti', 'Memahami Darsana dan Moksa.', 'Sraddha dan Bhakti', 58, null),
  ('pah-f-3', 'pah', 'F', 'SMA/MA', 'XI–XII', 3, 'Susila', 'Memahami konsep Keluarga Sukhinah dan Karakter Kepemimpinan Hindu.', 'Susila', 58, null),
  ('pah-f-4', 'pah', 'F', 'SMA/MA', 'XI–XII', 4, 'Acara', 'Memahami Seni Keagamaan Hindu serta Yogacara dalam Mantra, Yantra, dan Tantra.', 'Acara', 58, null),
  ('pah-f-5', 'pah', 'F', 'SMA/MA', 'XI–XII', 5, 'Sejarah Agama Hindu', 'Memahami Sejarah Organisasi Keagamaan Hindu di Indonesia.', 'Sejarah Agama Hindu', 59, null),
  ('pab-a-1', 'pab', 'A', 'SD/MI', 'I–II', 1, 'Sejarah', 'Memahami identitas diri dan keluarganya, serta memiliki keterbukaan untuk menghargai perbedaan identitas dan budaya teman-temannya di lingkungan rumah, sekolah, dan rumah ibadah. murid mengamalkan sifat-sifat kehidupan para Bodhisattva, para Buddha, siswa Buddha atau tokoh Buddhis inspiratif dalam menyayangi diri sendiri dengan menjaga kesehatan fisik dan batin, membiasakan diri untuk bersikap hormat dan menjaga ucapan di lingkungannya sesuai kisah Jataka.', 'Sejarah', 62, null),
  ('pab-a-2', 'pab', 'A', 'SD/MI', 'I–II', 2, 'Ritual', 'Memahami identitas agama Buddha dan kepercayaan lainnya dalam suatu kelompok dengan anggota yang beragam identitas agama dan kepercayaan. murid memahami simbol-simbol keagamaan Buddha, agama dan kepercayaan lain di lingkungan rumah dan sekolahnya.', 'Ritual', 62, null),
  ('pab-a-3', 'pab', 'A', 'SD/MI', 'I–II', 3, 'Etika', 'Mengamalkan aturan dan sopan santun di lingkungan rumah, sekolah, dan rumah ibadah. murid memahami pergaulan untuk mempertahankan hidup dalam hubungannya dengan orang lain. murid memahami musyawarah sederhana untuk mufakat di lingkungan sekolahnya berlandaskan nilai-nilai empat sifat luhur, hukum karma dan Pancasila dasar negara berdasarkan pembelajaran ramah anak serta mencerminkan kehidupan yang moderat.', 'Etika', 63, null),
  ('pab-b-1', 'pab', 'B', 'SD/MI', 'III–IV', 1, 'Sejarah', 'Memahami identitas Buddha Sakyamuni, sebagai dasar keyakinan terhadap Agama Buddha. murid memahami budaya dan bahasa dalam agama Buddha serta memiliki keterbukaan untuk menghargai perbedaan identitas dan budaya orang lain di lingkungan tempat tinggalnya. murid meneladan Buddha Sakyamuni dalam menghargai sesama manusia, menyelesaikan masalah pergaulan di lingkungan terdekatnya, lingkungan sekolah dan rumah ibadah.', 'Sejarah', 63, null),
  ('pab-b-2', 'pab', 'B', 'SD/MI', 'III–IV', 2, 'Ritual', 'Memahami doa Buddhis dalam kegiatan sehari-hari berdasarkan keyakinan kepada Ketuhanan Yang Maha Esa dan Triratna. murid menghargai identitas masing-masing aliran atau tradisi dalam agama Buddha dan bersatu dalam perbedaan.', 'Ritual', 63, null),
  ('pab-b-3', 'pab', 'B', 'SD/MI', 'III–IV', 3, 'Etika', 'Mengamalkan nilai-nilai Pancasila Buddhis berlandaskan pada nilai-nilai Hukum Sebab Akibat yang Saling Bergantungan dalam melaksanakan aturan dan sopan santun; murid mengamalkan kesempurnaan (pāramī), sikap tolong menolong antarsesama dalam menyelesaikan masalah sosial, kebersihan, dan kelestarian lingkungan secara musyawarah mufakat di rumah, sekolah, dan rumah ibadah sebagai dasar keyakinan terhadap Agama Buddha, melalui pembelajaran ramah anak serta mencerminkan kehidupan yang moderat.', 'Etika', 64, null),
  ('pab-c-1', 'pab', 'C', 'SD/MI', 'V–VI', 1, 'Sejarah', 'Meneladani Buddha Sakyamuni dalam menghadapi hambatan untuk meraih kesuksesan; meneladan kehidupan Buddha Sakyamuni dalam menyelesaikan masalah kehidupan individu dan sosial; murid memahami konsep dasar musyawarah mufakat dalam kehidupan Buddha Sakyamuni.', 'Sejarah', 64, null),
  ('pab-c-2', 'pab', 'C', 'SD/MI', 'V–VI', 2, 'Ritual', 'Memahami keragaman upacara puja dan meditasi ketenangan dari berbagai aliran atau tradisi Agama Buddha. murid mengamalkan sikap bersatu dalam perbedaan dengan berperan serta melakukan dialog moderasi beragama.', 'Ritual', 64, null),
  ('pab-c-3', 'pab', 'C', 'SD/MI', 'V–VI', 3, 'Etika', 'Mengamalkan nilai-nilai Buddhadharma, Pancasila Buddhis, dan nilai-nilai Pancasila dasar negara berlandaskan pada nilai-nilai Hukum Sebab Akibat yang Saling Bergantungan. murid memahami hak dan kewajiban, permasalahan dan solusinya di rumah, sekolah, dan rumah ibadah sebagai dasar keyakinan terhadap Agama Buddha, melalui pembelajaran ramah anak serta mencerminkan kehidupan yang moderat.', 'Etika', 64, null),
  ('pab-d-1', 'pab', 'D', 'SMP/MTs', 'VII–IX', 1, 'Sejarah', 'Memahami sifat-sifat Buddha Sakyamuni, para penyokong Buddha, siswa-siswa utama, tokoh Buddhis inspiratif, peristiwa monumental setelah Buddha Sakyamuni Parinibbana, untuk diteladan dan dilestarikan dalam kehidupan sehari-hari dengan bijaksana dalam berperilaku terhadap diri sendiri, sesama manusia, masyarakat, dan lingkungan sekitar.', 'Sejarah', 65, null),
  ('pab-d-2', 'pab', 'D', 'SMP/MTs', 'VII–IX', 2, 'Ritual', 'Memahami meditasi hidup berkesadaran, budaya menghormat (pūja), hari raya agama Buddha, tempat-tempat ziarah Agama Buddha, melakukan ziarah ke tempat suci Agama Buddha, kunjungan ke tempat ibadah agama dan kepercayaan lain, menghargai tradisi Agama Buddha di Indonesia, dan melakukan dialog kerukunan umat beragama.', 'Ritual', 65, null),
  ('pab-d-3', 'pab', 'D', 'SMP/MTs', 'VII–IX', 3, 'Etika', 'Memahami nilai-nilai ajaran moralitas, jalan Bodhisattva yaitu Paññadika Bodhisattva, Saddhadika Bodhisattva, Viriyadika Bodhisattva; hukum karma dan kelahiran kembali, hak dan kewajiban moral terhadap sesama dan lingkungan, untuk mewujudkan kehidupan yang harmonis sebagai warga negara dalam menentukan sikap terhadap kesetaraan gender, pergaulan dan permasalahan remaja di lingkungan sekitar melalui pembelajaran ramah anak serta mencerminkan kehidupan yang moderat.', 'Etika', 65, null),
  ('pab-e-1', 'pab', 'E', 'SMA/MA', 'X', 1, 'Sejarah', 'Memahami penyiaran Agama Buddha, meneladan perjuangan pelaku sejarah Agama Buddha masa kini.', 'Sejarah', 66, null),
  ('pab-e-2', 'pab', 'E', 'SMA/MA', 'X', 2, 'Ritual', 'Memahami meditasi ketenangan batin dengan keyakinan.', 'Ritual', 66, null),
  ('pab-e-3', 'pab', 'E', 'SMA/MA', 'X', 3, 'Etika', 'Memahami nilai-nilai moderasi beragama berdasarkan Buddhadharma sebagai dasar dalam memaknai fenomena dan masalah kehidupan. murid memahami ilmu pengetahuan dan teknologi berdasarkan nilai-nilai agama Buddha. murid memahami nilai-nilai Hukum Kebenaran Mutlak melalui pembelajaran ramah anak serta mencerminkan kehidupan yang moderat.', 'Etika', 66, null),
  ('pab-f-1', 'pab', 'F', 'SMA/MA', 'XI–XII', 1, 'Sejarah', 'Memahami sikap tokoh pendukung Agama Buddha, pelaku sejarah Buddhis lokal, nasional, dan dunia masa kini; Budaya Buddhis, keragaman agama, maupun bangsa; Komunikasi lintas budaya, lintas aliran atau tradisi agama Buddha dengan bersikap bijaksana dan terbuka.', 'Sejarah', 66, null),
  ('pab-f-2', 'pab', 'F', 'SMA/MA', 'XI–XII', 2, 'Ritual', 'Melaksanakan Upacara keagamaan disertai keyakinan dan kebijaksanaan serta menghargai orang lain yang melakukan ritual keagamaan sesuai dengan agama dan kepercayaannya. murid memahami nilai-nilai Agama Buddha dengan kearifan lokal. Berperan aktif dalam kegiatan aksi sosial dan budaya sebagai wujud individu yang beragama dalam kehidupan bermasyarakat, berbangsa, dan bernegara.', 'Ritual', 67, null),
  ('pab-f-3', 'pab', 'F', 'SMA/MA', 'XI–XII', 3, 'Etika', 'Memahami alam semesta dan alam kehidupan berdasarkan nilai-nilai Hukum Kebenaran Mutlak, Empat Kebenaran Mulia, Hukum Karma, Punabhava, Hukum Tiga Corak Universal, dan Hukum Sebab Musabab Yang Saling Bergantungan. murid memahami fenomena dalam menghadapi masalah kehidupan perekonomian di dunia dan isu-isu global, dengan kebijaksanaan melalui pembelajaran ramah anak serta mencerminkan kehidupan yang moderat.', 'Etika', 67, null),
  ('pakh-a-1', 'pakh', 'A', 'SD/MI', 'I–II', 1, 'Sejarah Suci', 'Memahami riwayat dan keluarga Nabi Kŏngzĭ (孔 子), kisah keteladanan bakti para tokoh agama Khonghucu (Rújiào 儒教), kisah keteladanan sifat solidaritas sesama sahabat dari tokoh agama Khonghucu.', 'Sejarah Suci', 71, null),
  ('pakh-a-2', 'pakh', 'A', 'SD/MI', 'I–II', 2, 'Kitab Suci', 'Memahami ayat-ayat suci yang terdapat dalam kitab Bakti (Xiàojīng 孝经), Sìshū (四书) dan Wŭjīng (五经) yang berkaitan dengan kisah anak berbakti dan keteladanan Nabi Kŏngzĭ (孔子).', 'Kitab Suci', 71, null),
  ('pakh-a-3', 'pakh', 'A', 'SD/MI', 'I–II', 3, 'Keimanan', 'Memahami konsep Tiān (天) dalam agama Khonghucu bahwa manusia diciptakan Tiān (天) melalui kedua orang tua dan peran keberadaan leluhur dalam kehidupan manusia serta Nabi Kŏngzĭ (孔子) sebagai genta rohani Tiān (天), Tiān Zhī Mùduó (天之木铎).', 'Keimanan', 71, null),
  ('pakh-a-4', 'pakh', 'A', 'SD/MI', 'I–II', 4, 'Tata Ibadah', 'Memahami sikap dalam berdoa dan menghormat, sembahyang kepada Tiān (天), Nabi Kŏngzĭ (孔子), dan leluhur serta perlengkapan sembahyang di altar.', 'Tata Ibadah', 71, null),
  ('pakh-a-5', 'pakh', 'A', 'SD/MI', 'I–II', 5, 'Perilaku Jūnzĭ (君子)', 'Memahami sikap bakti dan hormat kepada orang tua sebagai wujud hormat kepada Tiān (天), pembiasaan berdoa sebelum maupun sesudah beraktivitas, dan sikap toleransi dengan teman, serta sikap tanggung jawab terhadap kebutuhan diri sendiri.', 'Perilaku Jūnzĭ (君子)', 71, null),
  ('pakh-b-1', 'pakh', 'B', 'SD/MI', 'III–IV', 1, 'Sejarah Suci', 'Memahami tentang watak sejati (xìng 性) menurut pendapat Mèngzĭ (孟子), sikap teladan dari murid-murid Nabi Kŏngzĭ (孔子), riwayat Nabi Kŏngzĭ (孔子) sebagai genta rohani Tiān (天) (Tiān Zhī Mùduó 天之木铎), tugas suci pengembaraan Nabi Kŏngzĭ (孔子), Zhū Xī (朱熹) sebagai tokoh pembaharuan agama Khonghucu (Rújiào 儒教), keteladanan ibunda Nabi Kŏngzĭ (孔 子), ibunda Mèngzĭ (孟子), ibunda Ōuyáng Xiū (欧 阳修), dan ibunda Yuè Fēi (岳飛).', 'Sejarah Suci', 72, null),
  ('pakh-b-2', 'pakh', 'B', 'SD/MI', 'III–IV', 2, 'Kitab Suci', 'Memahami tiga kesukaan yang membawa faedah dan tiga kesukaan yang membawa celaka, bagian-bagian kitab suci yang pokok (Sìshū 四书) dan yang mendasari (Wŭjīng 五经), ayat dalam kitab Sìshū (四书) yang berkaitan dengan delapan kebajikan (bādé 八德).', 'Kitab Suci', 72, null),
  ('pakh-b-3', 'pakh', 'B', 'SD/MI', 'III–IV', 3, 'Keimanan', 'Memahami makna persembahyangan kepada Tiān (天), Nabi Kŏngzĭ (孔子), para suci (shénmíng 神明) dan leluhur, tanda-tanda khusus menjelang wafat Nabi Kŏngzĭ (孔子), nilai-nilai delapan keimanan (bāchéngzhēnguī 八诚箴规), cita-cita mulia dan semangat belajar Nabi Kŏngzĭ (孔子).', 'Keimanan', 72, null),
  ('pakh-b-4', 'pakh', 'B', 'SD/MI', 'III–IV', 4, 'Tata Ibadah', 'Memahami peralatan dan perlengkapan sembahyang dan penataannya di altar leluhur, tata cara menancapkan dupa dalam bersembahyang kepada Tiān (天), Nabi Kŏngzĭ (孔 子), para suci (shénmíng 神明) dan leluhur, sikap berdoa (bào xīn bādé 抱心八德), tata cara dan pelaksanaan ibadah di lĭtáng (礼堂)/miào (庙) /klenteng/kelenteng.', 'Tata Ibadah', 72, null),
  ('pakh-b-5', 'pakh', 'B', 'SD/MI', 'III–IV', 5, 'Perilaku Jūnzĭ (君子)', 'Memahami sikap dan perilaku luhur Nabi Kŏngzĭ (孔子), teladan murid-murid Nabi Kŏngzĭ (孔子), menghargai waktu, berhati-hati, saling mengasihi sesama manusia, perilaku sesuai dengan delapan kebajikan (bādé八德), mudah bergaul tanpa membedakan, mau mengakui kesalahan dan memperbaiki diri.', 'Perilaku Jūnzĭ (君子)', 73, null),
  ('pakh-c-1', 'pakh', 'C', 'SD/MI', 'V–VI', 1, 'Sejarah Suci', 'Memahami wahyu Tiān (天) yang diterima oleh para nabi dan raja suci, tokoh-tokoh Rújiào (儒 教) serta sumbangsih pemikirannya, sejarah perkembangan agama Khonghucu di Indonesia.', 'Sejarah Suci', 73, null),
  ('pakh-c-2', 'pakh', 'C', 'SD/MI', 'V–VI', 2, 'Kitab Suci', 'Memahami ayat-ayat dalam kitab Sìshū (四书) dan Wŭjīng (五经) tentang Nabi Kŏngzĭ (孔子) sebagai Tiān Zhī Mùduó (天之木铎), persaudaraan dalam pergaulan, rasa cinta tanah air, empat pantangan sìwù (四勿), dan yang berhubungan dengan konsep sāncái (三才).', 'Kitab Suci', 73, null),
  ('pakh-c-3', 'pakh', 'C', 'SD/MI', 'V–VI', 3, 'Keimanan', 'Memahami bahwa sembahyang adalah pokok dari agama, definisi iman, hukum yīnyáng (阴阳) sebagai dasar hukum alam semesta, konsep Tiga Dasar Kenyataan (sāncái 三才).', 'Keimanan', 73, null),
  ('pakh-c-4', 'pakh', 'C', 'SD/MI', 'V–VI', 4, 'Tata Ibadah', 'Memahami hari raya/sembahyang kepada Tiān (天), Nabi Kŏngzĭ (孔子), shénmíng (神明), dan leluhur sebagai wujud kesusilaan (lĭ 礼), perlengkapan dan peralatan sembahyang sehingga menumbuhkan keimanan dan kepribadian luhur.', 'Tata Ibadah', 73, null),
  ('pakh-c-5', 'pakh', 'C', 'SD/MI', 'V–VI', 5, 'Perilaku Jūnzĭ (君子)', 'Memahami sikap cinta kasih kepada seluruh makhluk ciptaan Tiān (天), cinta tanah air, hidup tepa salira dan harmonis kepada sesama, bakti kepada Tiāndìrén (天地人), prinsip empat pantangan (sìwù 四勿) dan lima hubungan kemasyarakatan (wŭlún 五伦) dalam keseharian.', 'Perilaku Jūnzĭ (君子)', 74, null),
  ('pakh-d-1', 'pakh', 'D', 'SMP/MTs', 'VII–IX', 1, 'Sejarah Suci', 'Memahami rangkaian wahyu dalam agama Khonghucu dari nabi purba, raja suci sampai dengan Nabi Kŏngzĭ (孔子), keteladanan murid-murid Nabi Kŏngzĭ (孔子) dan orang-orang besar, serta perkembangan kehidupan beragama dan bernegara di Indonesia.', 'Sejarah Suci', 74, null),
  ('pakh-d-2', 'pakh', 'D', 'SMP/MTs', 'VII–IX', 2, 'Kitab Suci', 'Memahami teks kitab Sìshū (四书) dan Wŭjīng (五 经) serta Xiàojīng (孝经) sebagai sumber pengetahuan yang melandasi sejarah suci, keimanan, tata ibadah dan keteladanan perilaku Jūnzĭ (君子).', 'Kitab Suci', 74, null),
  ('pakh-d-3', 'pakh', 'D', 'SMP/MTs', 'VII–IX', 3, 'Keimanan', 'Memahami Tiān (天), kenabian Nabi Kŏngzĭ (孔 子), dan watak sejati (xìng 性).', 'Keimanan', 74, null),
  ('pakh-d-4', 'pakh', 'D', 'SMP/MTs', 'VII–IX', 4, 'Tata Ibadah', 'Memahami ritual keagamaan kepada Tiān (天), dì (地) dan rén (人) dalam agama Khonghucu.', 'Tata Ibadah', 74, null),
  ('pakh-d-5', 'pakh', 'D', 'SMP/MTs', 'VII–IX', 5, 'Perilaku Jūnzĭ (君子)', 'Memahami berperilaku sesuai dengan predikat yang diembannya baik sebagai diri pribadi, bagian dari keluarga, masyarakat, bangsa, negara dan dunia dengan berpedoman pada dìziguī (弟子规), wŭcháng (五常) dan delapan kebajikan (bādé 八德).', 'Perilaku Jūnzĭ (君子)', 74, null),
  ('pakh-e-1', 'pakh', 'E', 'SMA/MA', 'X', 1, 'Sejarah Suci', 'Memahami karya dan nilai keteladanan para nabi, raja suci dan tokoh Khonghucu, kisah hidup murid Nabi Kŏngzĭ (孔子).', 'Sejarah Suci', 75, null),
  ('pakh-e-2', 'pakh', 'E', 'SMA/MA', 'X', 2, 'Kitab Suci', 'Memahami fase perkembangan kitab-kitab suci agama Khonghucu dan bagian-bagian Kitab Wŭjīng (五经).', 'Kitab Suci', 75, null),
  ('pakh-e-3', 'pakh', 'E', 'SMA/MA', 'X', 3, 'Keimanan', 'Memahami kebesaran jalan suci Tiān (Tiāndào 天道), kekuasaan hukum suci Tiān (Tiānlĭ 天理), makna diturunkannya wahyu Tiān (天) dalam agama Khonghucu, konsep dasar dan prinsip yīnyáng (阴阳).', 'Keimanan', 75, null),
  ('pakh-e-4', 'pakh', 'E', 'SMA/MA', 'X', 4, 'Tata Ibadah', 'Memahami hakikat dan makna ibadah persembahyangan kepada Tiān (天).', 'Tata Ibadah', 75, null),
  ('pakh-e-5', 'pakh', 'E', 'SMA/MA', 'X', 5, 'Perilaku Jūnzĭ (君子)', 'Memahami hakikat dan sifat dasar manusia, serta sikap moderasi beragama.', 'Perilaku Jūnzĭ (君子)', 75, null),
  ('pakh-f-1', 'pakh', 'F', 'SMA/MA', 'XI–XII', 1, 'Sejarah Suci', 'Memahami prinsip moral yang diajarkan Mèngzĭ (孟子), kisah Raja Suci Yáo (尧) dan Shùn (舜), kisah Nabi Yī Yĭn (伊尹), jabatan yang pernah diemban oleh Nabi Kŏngzĭ (孔子) pada zaman chūnqiū (春秋), serta kontribusi dan situs sejarah ajaran Khonghucu di Indonesia dan dunia.', 'Sejarah Suci', 75, null),
  ('pakh-f-2', 'pakh', 'F', 'SMA/MA', 'XI–XII', 2, 'Kitab Suci', 'Memahami kitab suci yang pokok (Sìshū 四书), kitab suci yang mendasari (Wŭjīng 五经), serta ayat suci mengenai wŭcháng (五常) dan wŭlún (五 伦).', 'Kitab Suci', 76, null),
  ('pakh-f-3', 'pakh', 'F', 'SMA/MA', 'XI–XII', 3, 'Keimanan', 'Memahami bahwa manusia sebagai co-creator yang diciptakan oleh Tiān (天), makna sikap hidup zhōngshù (忠恕) sebagai pedoman hidup di dunia, Nabi Kŏngzĭ (孔子) sebagai Tiān Zhī Mùduó (天之木铎), serta teladan para nabi, shénmíng (神 明), dan leluhur.', 'Keimanan', 76, null),
  ('pakh-f-4', 'pakh', 'F', 'SMA/MA', 'XI–XII', 4, 'Tata Ibadah', 'Memahami ritual dan makna persembahyangan kepada Tiān (天), nabi, shénmíng (神明), leluhur dan makna agamis hari raya keagamaan, serta atribut rohaniwan Khonghucu.', 'Tata Ibadah', 76, null),
  ('pakh-f-5', 'pakh', 'F', 'SMA/MA', 'XI–XII', 5, 'Perilaku Jūnzĭ (君子)', 'Memahami perilaku bakti (xiào 孝) sebagai pokok kebajikan, perilaku cinta kasih, kebenaran, semangat belajar, dan konsep kebersamaan agung (dàtóng 大同).', 'Perilaku Jūnzĭ (君子)', 76, null),
  ('ppkn-a-1', 'ppkn', 'A', 'SD/MI', 'I–II', 1, 'Pancasila', 'Mengenal bendera negara, lagu kebangsaan, simbol dan sila-sila Pancasila dalam lambang negara Garuda Pancasila dan simbol Pancasila beserta sila-sila Pancasila; menerapkan nilai-nilai Pancasila di lingkungan keluarga.', 'Pancasila', 82, null),
  ('ppkn-a-2', 'ppkn', 'A', 'SD/MI', 'I–II', 2, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'Mengenal aturan di lingkungan keluarga; menunjukkan dan menceritakan sikap mematuhi aturan di lingkungan keluarga.', 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 82, null),
  ('ppkn-a-3', 'ppkn', 'A', 'SD/MI', 'I–II', 3, 'Bhinneka Tunggal Ika', 'Mengenal semboyan Bhinneka Tunggal Ika; mengidentifikasi dan menghargai identitas dirinya sesuai dengan jenis kelamin, hobi, bahasa, serta agama dan kepercayaan di lingkungan sekitar.', 'Bhinneka Tunggal Ika', 83, null),
  ('ppkn-a-4', 'ppkn', 'A', 'SD/MI', 'I–II', 4, 'Negara Kesatuan Republik Indonesia', 'Mengenal karakteristik lingkungan tempat tinggal dan sekolah, sebagai bagian dari wilayah Negara Kesatuan Republik Indonesia; menceritakan dan mempraktikkan bekerja sama menjaga lingkungan sekitar dalam keberagaman.', 'Negara Kesatuan Republik Indonesia', 83, null),
  ('ppkn-b-1', 'ppkn', 'B', 'SD/MI', 'III–IV', 1, 'Pancasila', 'Mengidentifikasi makna sila-sila Pancasila, dan penerapannya dalam kehidupan sehari-hari; mengenal karakter para perumus Pancasila; menunjukkan sikap bangga menjadi anak Indonesia yang memiliki bahasa Indonesia sebagai bahasa persatuan di lingkungan sekitar.', 'Pancasila', 83, null),
  ('ppkn-b-2', 'ppkn', 'B', 'SD/MI', 'III–IV', 2, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'Mengidentifikasi dan melaksanakan aturan di sekolah dan lingkungan tempat tinggal; mengidentifikasi dan menerapkan hak yang didapat dan kewajiban sebagai anggota keluarga dan sebagai warga sekolah.', 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 83, null),
  ('ppkn-b-3', 'ppkn', 'B', 'SD/MI', 'III–IV', 3, 'Bhinneka Tunggal Ika', 'Membedakan dan menghargai identitas, keluarga, dan teman-temannya sesuai budaya, suku bangsa, bahasa, agama dan kepercayaannya di lingkungan sekitar.', 'Bhinneka Tunggal Ika', 83, null),
  ('ppkn-b-4', 'ppkn', 'B', 'SD/MI', 'III–IV', 4, 'Negara Kesatuan Republik Indonesia', 'Mengidentifikasi lingkungan tempat tinggal (RT, RW, desa atau kelurahan, dan kecamatan) sebagai bagian dari wilayah Negara Kesatuan Republik Indonesia; menunjukkan perilaku bekerja sama dalam berbagai bentuk keberagaman suku bangsa, sosial, dan budaya di Indonesia yang terikat persatuan dan kesatuan di lingkungan sekitar.', 'Negara Kesatuan Republik Indonesia', 84, null),
  ('ppkn-c-1', 'ppkn', 'C', 'SD/MI', 'V–VI', 1, 'Pancasila', 'Memahami kronologi sejarah kelahiran Pancasila; meneladani sikap para perumus Pancasila dan menerapkan di lingkungan masyarakat; menghubungkan sila-sila dalam Pancasila sebagai suatu kesatuan yang utuh; menguraikan makna nilai-nilai Pancasila sebagai dasar negara, dan pandangan hidup bangsa.', 'Pancasila', 84, null),
  ('ppkn-c-2', 'ppkn', 'C', 'SD/MI', 'V–VI', 2, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'Mengimplementasikan bentuk-bentuk norma, hak, dan kewajiban dalam kedudukannya sebagai warga negara; mengenal Pembukaan Undang-Undang Dasar Negara Republik Indonesia tahun 1945; mempraktikkan musyawarah untuk membuat kesepakatan dan aturan bersama, serta menerapkannya dalam lingkungan keluarga dan sekolah.', 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 84, null),
  ('ppkn-c-3', 'ppkn', 'C', 'SD/MI', 'V–VI', 3, 'Bhinneka Tunggal Ika', 'Menyajikan hasil identifikasi sikap menghormati, menjaga, dan melestarikan keberagaman budaya sesuai semboyan dalam bingkai Bhinneka Tunggal Ika di lingkungan sekitar.', 'Bhinneka Tunggal Ika', 84, null),
  ('ppkn-c-4', 'ppkn', 'C', 'SD/MI', 'V–VI', 4, 'Negara Kesatuan Republik Indonesia', 'Mengenal wilayahnya dalam konteks kabupaten/kota, dan provinsi sebagai bagian dari wilayah Negara Kesatuan Republik Indonesia; menunjukkan perilaku gotong royong untuk menjaga persatuan di lingkungan sekolah dan sekitar sebagai wujud bela negara.', 'Negara Kesatuan Republik Indonesia', 85, null),
  ('ppkn-d-1', 'ppkn', 'D', 'SMP/MTs', 'VII–IX', 1, 'Pancasila', 'Memahami sejarah kelahiran Pancasila; memahami kedudukan Pancasila sebagai dasar negara, pandangan hidup bangsa, dan ideologi negara serta penerapannya dalam kehidupan sehari-hari; memahami makna keterkaitan Pancasila dengan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Bhinneka Tunggal Ika, dan Negara Kesatuan Republik Indonesia.', 'Pancasila', 85, null),
  ('ppkn-d-2', 'ppkn', 'D', 'SMP/MTs', 'VII–IX', 2, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'Menerapkan norma dan aturan; memahami tata urutan peraturan perundang-undangan yang berlaku di Indonesia; menggunakan hak dan menerapkan kewajiban sebagai warga negara; memahami sejarah, fungsi, dan kedudukan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945; mempraktikkan kemerdekaan berpendapat sebagai warga negara dalam era keterbukaan informasi.', 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 85, null),
  ('ppkn-d-3', 'ppkn', 'D', 'SMP/MTs', 'VII–IX', 3, 'Bhinneka Tunggal Ika', 'Mengidentifikasi keberagaman suku bangsa, agama dan kepercayaan, ras, dan antargolongan dalam bingkai Bhinneka Tunggal Ika dan menerima keberagaman dalam kehidupan bermasyarakat; memahami pentingnya pelestarian tradisi, kearifan lokal, dan budaya daerah sebagai identitas nasional; menumbuhkan sikap tanggung jawab dan berperan aktif melestarikan praktik tradisi, kearifan lokal, dan budaya daerah dalam masyarakat global.', 'Bhinneka Tunggal Ika', 85, null),
  ('ppkn-d-4', 'ppkn', 'D', 'SMP/MTs', 'VII–IX', 4, 'Negara Kesatuan Republik Indonesia', 'Memahami Proklamasi Kemerdekaan Republik Indonesia; memahami wilayah Negara Kesatuan Republik Indonesia dalam konteks wawasan nusantara; berpartisipasi aktif untuk menjaga keutuhan wilayah Negara Kesatuan Republik Indonesia.', 'Negara Kesatuan Republik Indonesia', 86, null),
  ('ppkn-e-1', 'ppkn', 'E', 'SMA/MA', 'X', 1, 'Pancasila', 'Menganalisis cara pandang para perumus Pancasila tentang dasar negara; menganalisis kedudukan Pancasila sebagai dasar negara, pandangan hidup bangsa, dan ideologi negara.', 'Pancasila', 86, null),
  ('ppkn-e-2', 'ppkn', 'E', 'SMA/MA', 'X', 2, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'Menerapkan perilaku taat hukum berdasarkan peraturan yang berlaku untuk mewujudkan harmoni dengan sesama manusia dan lingkungan; menganalisis tata urutan peraturan perundang - undangan di Indonesia; menganalisis makna kedudukan Pancasila sebagai sumber dari segala sumber hukum negara.', 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 86, null),
  ('ppkn-e-3', 'ppkn', 'E', 'SMA/MA', 'X', 3, 'Bhinneka Tunggal Ika', 'Menyajikan makna semboyan Bhinneka Tunggal Ika sebagai modal sosial; dan memahami prinsip gotong royong sebagai perwujudan sistem ekonomi Pancasila yang inklusif dan berkeadilan.', 'Bhinneka Tunggal Ika', 87, null),
  ('ppkn-e-4', 'ppkn', 'E', 'SMA/MA', 'X', 4, 'Negara Kesatuan Republik Indonesia', 'Memahami peran dan kedudukannya sebagai warga Negara Indonesia; memahami sistem pertahanan dan keamanan negara; menganalisis peran Indonesia dalam hubungan antarnegara; serta memahami nilai-nilai Pancasila dalam konteks pembangunan nasional.', 'Negara Kesatuan Republik Indonesia', 87, null),
  ('ppkn-f-1', 'ppkn', 'F', 'SMA/MA', 'XI–XII', 1, 'Pancasila', 'Mendeskripsikan rumusan dan keterkaitan sila-sila dalam Pancasila; menganalisis peluang dan tantangan penerapan nilai-nilai Pancasila dalam kehidupan global dalam konteks Pancasila sebagai ideologi negara dan membiasakan perilaku yang sesuai dengan nilai-nilai Pancasila sebagai identitas nasional dalam kehidupan sehari-hari.', 'Pancasila', 87, null),
  ('ppkn-f-2', 'ppkn', 'F', 'SMA/MA', 'XI–XII', 2, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'Menganalisis dinamika pemberlakuan Undang-Undang Dasar 1945; menunjukkan sikap demokratis berdasarkan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 dalam era keterbukaan informasi; menganalisis kasus pelanggaran hak dan pengingkaran kewajiban warga negara dan merumuskan solusi dari permasalahan tersebut sebagai upaya perlindungan hukum; menganalisis makna kesatuan Pancasila dengan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945.', 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 87, null),
  ('ppkn-f-3', 'ppkn', 'F', 'SMA/MA', 'XI–XII', 3, 'Bhinneka Tunggal Ika', 'Menganalisis potensi konflik dan memberi solusi yang berkeadilan terhadap permasalahan keberagaman di masyarakat; merancang kegiatan bersama dengan prinsip gotong royong dalam praktik hidup sehari-hari.', 'Bhinneka Tunggal Ika', 88, null),
  ('ppkn-f-4', 'ppkn', 'F', 'SMA/MA', 'XI–XII', 4, 'Negara Kesatuan Republik Indonesia', 'Mendemonstrasikan praktik demokrasi berlandaskan Pancasila dalam kehidupan berbangsa dan bernegara; menganalisis dan merumuskan solusi terkait ancaman, tantangan, hambatan, dan gangguan (ATHG) yang dihadapi Indonesia; menganalisis sistem pemerintahan Indonesia, dan peran lembaga-lembaga negara dalam bidang politik, ekonomi, sosial, budaya, pertahanan dan keamanan.', 'Negara Kesatuan Republik Indonesia', 88, null),
  ('bindo-a-1', 'bindo', 'A', 'SD/MI', 'I–II', 1, 'Menyimak', 'Memahami informasi dari teks nonsastra berbentuk teks aural (teks yang dibacakan dan/atau didengarkan) berupa percakapan yang berkaitan dengan diri, keluarga, dan/atau lingkungan sekitar; dan memahami pesan teks sastra berbentuk teks aural.', 'Menyimak', 94, null),
  ('bindo-a-2', 'bindo', 'A', 'SD/MI', 'I–II', 2, 'Membaca dan Memirsa', 'Membaca kata-kata sederhana dengan fasih dari bacaan dan/atau tayangan yang dipirsa tentang diri, keluarga, kesehatan, dan/atau lingkungan sekitar; dan memahami isi bacaan dan/atau tayangan yang dipirsa tentang diri, keluarga, kesehatan, dan/atau lingkungan sekitar.', 'Membaca dan Memirsa', 94, null),
  ('bindo-a-3', 'bindo', 'A', 'SD/MI', 'I–II', 3, 'Berbicara dan Mempresentasikan', 'Merespons dengan bertanya tentang sesuatu, menjawab, dan menanggapi komentar orang lain (teman, pendidik, dan/atau orang dewasa) dengan baik dan santun dalam suatu percakapan tentang diri, keluarga, kesehatan, dan/atau lingkungan sekitar; mengungkapkan perasaan dan gagasan secara lisan dengan atau tanpa bantuan gambar; dan menceritakan kembali isi berbagai tipe teks yang dibaca, dipirsa, atau didengar tentang diri, keluarga, kesehatan, dan/atau lingkungan sekitar.', 'Berbicara dan Mempresentasikan', 94, null),
  ('bindo-a-4', 'bindo', 'A', 'SD/MI', 'I–II', 4, 'Menulis', 'Menulis permulaan dengan benar di atas kertas dan/atau melalui media digital; mengembangkan tulisan tangan yang semakin baik; dan menulis berbagai tipe teks sederhana tentang diri, keluarga, dan/atau lingkungan sekitar dengan beberapa kalimat sederhana.', 'Menulis', 94, null),
  ('bindo-b-1', 'bindo', 'B', 'SD/MI', 'III–IV', 1, 'Menyimak', 'Memahami ide pokok suatu informasi dari teks nonsastra berbentuk teks aural (teks yang dibacakan dan/atau didengarkan); dan memahami isi teks sastra berbentuk teks aural.', 'Menyimak', 95, null),
  ('bindo-b-2', 'bindo', 'B', 'SD/MI', 'III–IV', 2, 'Membaca dan Memirsa', 'Membaca kata-kata baru dengan fasih dari bacaan dan/atau tayangan yang dipirsa; dan memahami ide pokok, ide pendukung, pesan, dan informasi dalam teks sastra dan nonsastra berbentuk cetak dan/atau elektronik.', 'Membaca dan Memirsa', 95, null),
  ('bindo-b-3', 'bindo', 'B', 'SD/MI', 'III–IV', 3, 'Berbicara dan Mempresentasikan', 'Menyajikan pendapat dengan pilihan kata dan sikap tubuh/gestur yang sesuai, menggunakan volume dan intonasi yang tepat sesuai konteks; menanggapi diskusi sesuai tata cara; dan menceritakan kembali isi dan/atau informasi dari berbagai tipe teks yang dibaca, dipirsa, atau didengar.', 'Berbicara dan Mempresentasikan', 95, null),
  ('bindo-b-4', 'bindo', 'B', 'SD/MI', 'III–IV', 4, 'Menulis', 'Menulis berbagai tipe teks sederhana dengan rangkaian kalimat yang beragam; dan menggunakan kaidah kebahasaan dan kosakata baru yang memiliki makna denotatif untuk menulis teks sesuai dengan konteks.', 'Menulis', 95, null),
  ('bindo-c-1', 'bindo', 'C', 'SD/MI', 'V–VI', 1, 'Menyimak', 'Menganalisis informasi dari teks nonsastra berbentuk teks aural (teks yang dibacakan dan/atau didengarkan; dan menganalisis isi teks sastra berbentuk teks aural.', 'Menyimak', 96, null),
  ('bindo-c-2', 'bindo', 'C', 'SD/MI', 'V–VI', 2, 'Membaca dan Memirsa', 'Membaca kata-kata dengan berbagai pola kombinasi huruf dengan fasih dari bacaan dan/atau tayangan yang dipirsa; dan menganalisis informasi serta nilai-nilai dalam teks sastra dan nonsastra berwujud teks visual dan/atau audiovisual.', 'Membaca dan Memirsa', 96, null),
  ('bindo-c-3', 'bindo', 'C', 'SD/MI', 'V–VI', 3, 'Berbicara dan Mempresentasikan', 'Mempresentasikan gagasan dari berbagai tipe teks dengan efektif dan santun; dan menyampaikan perasaan berdasarkan fakta, imajinasi (dari diri sendiri dan orang lain) secara indah dan menarik dalam bentuk teks sastra dengan penggunaan kosakata secara kreatif.', 'Berbicara dan Mempresentasikan', 96, null),
  ('bindo-c-4', 'bindo', 'C', 'SD/MI', 'V–VI', 4, 'Menulis', 'Menulis berbagai tipe teks sederhana berdasarkan gagasan, hasil pengamatan, pengalaman, dan/atau imajinasi dengan rangkaian kalimat kompleks secara kreatif, menarik, dan/atau indah; dan menggunakan kaidah kebahasaan dan kosakata baru yang memiliki makna denotatif dan konotatif.', 'Menulis', 96, null),
  ('bindo-d-1', 'bindo', 'D', 'SMP/MTs', 'VII–IX', 1, 'Menyimak', 'Menganalisis gagasan, pandangan, arahan, dan/atau pesan dari teks nonsastra berbentuk teks aural (teks yang dibacakan dan/atau didengarkan); dan menganalisis unsur intrinsik teks sastra berbentuk teks aural.', 'Menyimak', 96, null),
  ('bindo-d-2', 'bindo', 'D', 'SMP/MTs', 'VII–IX', 2, 'Membaca dan Memirsa', 'Menganalisis informasi berupa gagasan, pandangan, arahan, dan/atau pesan dari berbagai tipe teks berwujud teks visual dan/atau audiovisual untuk menemukan makna yang tersurat dan tersirat; menginterpretasi informasi untuk mengungkapkan kepedulian dan/atau pendapat pro/kontra dari berbagai tipe teks berwujud teks visual dan/atau audiovisual; dan mengevaluasi kualitas dan/atau kredibilitas dari berbagai tipe teks berwujud teks visual dan/atau audiovisual menggunakan sumber informasi lain.', 'Membaca dan Memirsa', 97, null),
  ('bindo-d-3', 'bindo', 'D', 'SMP/MTs', 'VII–IX', 3, 'Berbicara dan Mempresentasikan', 'Mempresentasikan gagasan, pandangan, arahan, dan/atau pesan untuk tujuan pengajuan usul dan pemberian solusi dalam bentuk monolog, dialog logis, dan/atau berbagai tipe teks secara kritis dan kreatif; dan menyajikan ungkapan kepedulian dari berbagai tipe teks dan/atau teks multimodal.', 'Berbicara dan Mempresentasikan', 97, null),
  ('bindo-d-4', 'bindo', 'D', 'SMP/MTs', 'VII–IX', 4, 'Menulis', 'Menulis gagasan, pandangan, arahan, pesan, pengalaman, dan/atau imajinasi dalam berbagai tipe teks secara logis, kritis, kreatif, menarik, dan/atau indah; menulis ungkapan kepedulian dan/atau pendapat pro/kontra dalam berbagai tipe teks berbentuk teks multimodal; dan menggunakan kosakata baru yang memiliki makna denotatif, konotatif, dan kiasan untuk menulis.', 'Menulis', 97, null),
  ('bindo-e-1', 'bindo', 'E', 'SMA/MA', 'X', 1, 'Menyimak', 'Mengevaluasi gagasan, pandangan, arahan, dan/atau pesan dari teks nonsastra berbentuk teks aural (teks yang dibacakan dan/atau didengarkan); dan mengevaluasi unsur intrinsik dan ekstrinsik teks sastra berbentuk teks aural.', 'Menyimak', 98, null),
  ('bindo-e-2', 'bindo', 'E', 'SMA/MA', 'X', 2, 'Membaca dan Memirsa', 'Mengevaluasi informasi berupa gagasan, pandangan, arahan, dan/atau pesan dari berbagai tipe teks berwujud visual dan/atau audiovisual untuk menemukan makna yang tersurat dan tersirat; menginterpretasi informasi untuk mengungkapkan gagasan dan perasaan (simpati, peduli, dan empati) dari berbagai tipe teks berwujud teks visual dan/atau audiovisual secara kreatif; mengevaluasi kualitas dan/atau kredibilitas dari berbagai tipe teks berwujud teks visual dan/atau audiovisual menggunakan sumber informasi lain; dan membandingkan isi teks.', 'Membaca dan Memirsa', 98, null),
  ('bindo-e-3', 'bindo', 'E', 'SMA/MA', 'X', 3, 'Berbicara dan Mempresentasikan', 'Mempresentasikan gagasan, pandangan, arahan, dan/atau pesan berbagai tipe teks berbentuk monolog, dialog, dan/atau gelar wicara secara sistematis, kritis, dan/atau kreatif; dan mengungkapkan kepedulian dari berbagai tipe teks dan/atau teks multimodal secara kreatif.', 'Berbicara dan Mempresentasikan', 98, null),
  ('bindo-e-4', 'bindo', 'E', 'SMA/MA', 'X', 4, 'Menulis', 'Menulis gagasan, pandangan, arahan, pesan, dan/atau imajinasi dalam berbagai tipe teks secara logis, kritis, dan kreatif; dan memublikasikan hasil karya di media cetak, elektronik, dan/atau digital.', 'Menulis', 98, null),
  ('bindo-f-1', 'bindo', 'F', 'SMA/MA', 'XI–XII', 1, 'Menyimak', 'Mengevaluasi gagasan, perasaan, pandangan, arahan, dan/atau pesan dari teks nonsastra berbentuk teks aural (teks yang dibacakan dan/atau didengarkan); dan mengapresiasi teks sastra berbentuk teks aural.', 'Menyimak', 99, null),
  ('bindo-f-2', 'bindo', 'F', 'SMA/MA', 'XI–XII', 2, 'Membaca dan Memirsa', 'Mengevaluasi informasi berupa gagasan, perasaan, pandangan, arahan, dan/atau pesan dari berbagai tipe teks berwujud teks visual dan/atau audiovisual untuk menemukan makna yang tersurat dan tersirat berdasarkan kaidah logika berpikir; merefleksi gagasan dan pandangan berdasarkan kaidah logika berpikir dari berbagai tipe teks berwujud teks visual dan/atau audiovisual; dan mengapresiasi berbagai tipe teks berwujud teks visual dan/atau audiovisual.', 'Membaca dan Memirsa', 99, null),
  ('bindo-f-3', 'bindo', 'F', 'SMA/MA', 'XI–XII', 3, 'Berbicara dan Mempresentasikan', 'Mempresentasikan gagasan, perasaan, pandangan, arahan, pesan, dan/atau kreativitas berbahasa dalam berbagai tipe teks berbentuk monolog, dialog, dan/atau gelar wicara dan/atau berbagai tipe teks secara logis, sistematis, kritis, dan kreatif sesuai dengan norma kesopanan dan budaya Indonesia; menyajikan karya sastra secara kreatif dan menarik; dan mempertahankan hasil penelitian dengan argumentasi.', 'Berbicara dan Mempresentasikan', 99, null),
  ('bindo-f-4', 'bindo', 'F', 'SMA/MA', 'XI–XII', 4, 'Menulis', 'Menulis gagasan, pandangan, imajinasi, dan/atau pengetahuan metakognisi dalam berbagai tipe teks secara logis, kritis, dan kreatif; dan mempublikasikan hasil karya di media cetak, elektronik, dan/atau digital.', 'Menulis', 99, null),
  ('bindo-tl-f-1', 'bindo-tl', 'F', 'SMA/MA', 'XI–XII', 1, 'Menyimak', 'Mengevaluasi teks nonsastra berbentuk teks aural yang digunakan dalam konteks sosial, akademis, dan dunia kerja; dan mengapresiasi teks sastra Indonesia dan teks sastra dunia berbentuk teks aural dan teks audio.', 'Menyimak', 106, null),
  ('bindo-tl-f-2', 'bindo-tl', 'F', 'SMA/MA', 'XI–XII', 2, 'Membaca dan Memirsa', 'Mengevaluasi berbagai teks yang digunakan dalam konteks sosial, akademis, dan/atau dunia kerja berbentuk cetak dan digital; dan mengapresiasi teks sastra Indonesia dan teks sastra dunia yang dibaca dan dipirsa.', 'Membaca dan Memirsa', 106, null),
  ('bindo-tl-f-3', 'bindo-tl', 'F', 'SMA/MA', 'XI–XII', 3, 'Berbicara dan Mempresentasikan', 'Mempresentasikan berbagai teks dalam konteks sosial, akademis, dan/atau dunia kerja dalam berbagai media; dan mempresentasikan teks sastra Indonesia dan teks sastra dunia dalam bentuk digital atau pertunjukan.', 'Berbicara dan Mempresentasikan', 106, null),
  ('bindo-tl-f-4', 'bindo-tl', 'F', 'SMA/MA', 'XI–XII', 4, 'Menulis', 'Menulis berbagai tipe teks dalam konteks sosial, akademis, dan dunia kerja; memodifikasi teks sastra Indonesia dan teks sastra dunia ke dalam bentuk multimedia lisan/cetak atau digital; dan mempublikasikan hasil karya baik di media cetak maupun digital.', 'Menulis', 106, null),
  ('mtk-a-1', 'mtk', 'A', 'SD/MI', 'I–II', 1, 'Bilangan', 'Menunjukkan pemahaman dan memiliki intuisi bilangan (number sense) pada bilangan cacah sampai 100; membaca, menulis, menentukan nilai tempat, membandingkan, mengurutkan, serta melakukan komposisi (menyusun) dan dekomposisi (mengurai) bilangan; melakukan operasi penjumlahan dan pengurangan menggunakan benda-benda konkret yang banyaknya sampai 20; dan menunjukkan pemahaman pecahan sebagai bagian dari keseluruhan melalui konteks membagi sebuah benda atau kumpulan benda sama banyak (pecahan yang diperkenalkan adalah setengah dan seperempat).', 'Bilangan', 111, null),
  ('mtk-a-2', 'mtk', 'A', 'SD/MI', 'I–II', 2, 'Aljabar', 'Menunjukan pemahaman makna simbol matematika "=" dalam suatu kalimat matematika yang terkait dengan penjumlahan dan pengurangan bilangan cacah sampai 20 menggunakan gambar. Contoh: Murid dapat mengenali, meniru, dan melanjutkan pola bukan bilangan (misalnya, gambar, warna, bunyi/suara).', 'Aljabar', 111, null),
  ('mtk-a-3', 'mtk', 'A', 'SD/MI', 'I–II', 3, 'Pengukuran', 'Membandingkan panjang dan berat benda secara langsung, dan membandingkan durasi waktu; mengukur dan mengestimasi panjang dan berat benda menggunakan satuan tidak baku.', 'Pengukuran', 112, null),
  ('mtk-a-4', 'mtk', 'A', 'SD/MI', 'I–II', 4, 'Geometri', 'Mengenal berbagai bangun datar (segitiga, segiempat, segi banyak, lingkaran) dan bangun ruang (balok, kubus, kerucut, dan bola); melakukan komposisi (penyusunan) dan dekomposisi (penguraian) suatu bangun datar (segitiga, segiempat, dan segi banyak); dan menentukan posisi benda terhadap benda lain (kanan, kiri, depan belakang, bawah, atas).', 'Geometri', 112, null),
  ('mtk-a-5', 'mtk', 'A', 'SD/MI', 'I–II', 5, 'Analisis Data dan Peluang', 'Mengurutkan, menyortir, mengelompokkan, membandingkan, dan menyajikan data dari banyak benda dengan menggunakan turus dan piktogram paling banyak 4 kategori.', 'Analisis Data dan Peluang', 112, null),
  ('mtk-b-1', 'mtk', 'B', 'SD/MI', 'III–IV', 1, 'Bilangan', 'Memiliki pemahaman dan intuisi bilangan (number sense) pada bilangan cacah sampai 10.000; membaca, menulis, membandingkan, dan mengurutkan bilangan; menentukan dan menggunakan nilai tempat; melakukan komposisi dan dekomposisi bilangan cacah sampai 10.000. Murid dapat melakukan dan menyelesaikan masalah operasi bilangan penjumlahan dan pengurangan bilangan cacah sampai 1.000; melakukan dan menyelesaikan masalah operasi perkalian dan pembagian bilangan cacah sampai 100 dengan bantuan benda konkret, gambar dan simbol; mengenal kelipatan dan faktor. Murid dapat melakukan perbandingan dan pengurutan pecahan dengan pembilang satu dan antar pecahan dengan penyebut yang sama; mengenal dan dapat menerapkan pecahan senilai, memiliki intuisi pecahan dan desimal, serta dapat menentukan pecahan sebagai desimal dan persen.', 'Bilangan', 112, null),
  ('mtk-b-2', 'mtk', 'B', 'SD/MI', 'III–IV', 2, 'Aljabar', 'Menemukan nilai yang tidak diketahui dalam kalimat matematika yang melibatkan penjumlahan dan pengurangan pada bilangan cacah sampai 100, dengan menggunakan sifat-sifat bilangan dan operasinya. Murid dapat mengidentifikasi, meniru, dan mengembangkan pola gambar atau objek sederhana dan pola bilangan membesar dan mengecil yang dapat melibatkan penjumlahan dan pengurangan pada bilangan cacah sampai 100.', 'Aljabar', 113, null),
  ('mtk-b-3', 'mtk', 'B', 'SD/MI', 'III–IV', 3, 'Pengukuran', 'Mengukur panjang dan berat benda menggunakan satuan baku; menentukan hubungan antar-satuan baku panjang (cm, m) dan antar-satuan berat (g, kg); serta mengukur dan mengestimasi luas dan volume menggunakan satuan tidak baku dan satuan baku berupa bilangan cacah.', 'Pengukuran', 113, null),
  ('mtk-b-4', 'mtk', 'B', 'SD/MI', 'III–IV', 4, 'Geometri', 'Mendeskripsikan ciri berbagai bentuk bangun datar (segiempat, segitiga, segi banyak); menyusun (komposisi) dan mengurai (dekomposisi) berbagai bangun datar dengan lebih dari satu cara jika memungkinkan.', 'Geometri', 114, null),
  ('mtk-b-5', 'mtk', 'B', 'SD/MI', 'III–IV', 5, 'Analisis Data dan Peluang', 'Mengurutkan, membandingkan, menyajikan, menganalisis dan menginterpretasi data dalam bentuk tabel, diagram gambar, piktogram, dan diagram batang (skala satu satuan).', 'Analisis Data dan Peluang', 114, null),
  ('mtk-c-1', 'mtk', 'C', 'SD/MI', 'V–VI', 1, 'Bilangan', 'Menunjukkan pemahaman dan intuisi bilangan (number sense) pada bilangan cacah sampai 1.000.000; membaca, menulis, menentukan nilai tempat, membandingkan, mengurutkan, melakukan komposisi dan dekomposisi bilangan; menyelesaikan masalah yang berkaitan dengan uang; melakukan operasi penjumlahan, pengurangan, perkalian, dan pembagian bilangan cacah sampai 100.000; serta menyelesaikan masalah yang berkaitan dengan KPK dan FPB. Murid dapat membandingkan dan mengurutkan berbagai pecahan termasuk pecahan campuran, melakukan operasi penjumlahan dan pengurangan pecahan, serta melakukan operasi perkalian dan pembagian pecahan dengan bilangan asli; mengubah pecahan menjadi berbagai bentuk pecahan lain, serta membandingkan dan mengurutkan bilangan desimal (satu angka di belakang koma).', 'Bilangan', 114, null),
  ('mtk-c-2', 'mtk', 'C', 'SD/MI', 'V–VI', 2, 'Aljabar', 'Menemukan nilai yang belum diketahui dalam kalimat matematika yang melibatkan penjumlahan, pengurangan, perkalian, dan pembagian pada bilangan cacah sampai 1000 dengan menggunakan sifat-sifat bilangan dan operasinya. Murid dapat mengidentifikasi, meniru, dan mengembangkan pola bilangan membesar dan mengecil yang melibatkan perkalian dan pembagian; bernalar secara proporsional untuk menyelesaikan masalah sehari-hari dengan rasio satuan; menggunakan operasi perkalian dan pembagian dalam menyelesaikan masalah sehari- hari yang terkait dengan proporsi.', 'Aljabar', 115, null),
  ('mtk-c-3', 'mtk', 'C', 'SD/MI', 'V–VI', 3, 'Pengukuran', 'Menentukan keliling dan luas berbagai bentuk bangun datar (segitiga, segiempat, dan segi banyak) serta gabungannya; menghitung durasi waktu dan mengukur besar sudut pada bangun datar atau yang dibentuk dari dua garis berpotongan.', 'Pengukuran', 115, null),
  ('mtk-c-4', 'mtk', 'C', 'SD/MI', 'V–VI', 4, 'Geometri', 'Mengkonstruksi dan mengurai bangun ruang (kubus, balok, dan gabungannya) dan mengenali visualisasi spasial (bagian depan, atas, dan samping); membandingkan karakteristik antar bangun datar dan antar bangun ruang; serta menentukan lokasi pada peta yang menggunakan sistem berpetak.', 'Geometri', 115, null),
  ('mtk-c-5', 'mtk', 'C', 'SD/MI', 'V–VI', 5, 'Analisis Data dan Peluang', 'Mengurutkan, membandingkan, menyajikan, dan menganalisis data banyak benda dan data hasil pengukuran dalam bentuk gambar, piktogram, diagram batang, dan tabel frekuensi untuk mendapatkan informasi; menentukan kejadian dengan kemungkinan yang lebih besar atau lebih kecil dalam suatu percobaan acak.', 'Analisis Data dan Peluang', 115, null),
  ('mtk-d-1', 'mtk', 'D', 'SMP/MTs', 'VII–IX', 1, 'Bilangan', 'Membaca, menulis, dan membandingkan bilangan bulat, bilangan rasional, bilangan desimal, bilangan berpangkat bulat dan akar, bilangan dalam notasi ilmiah; menerapkan operasi aritmatika pada bilangan real, dan memberikan estimasi/perkiraan dalam menyelesaikan masalah (termasuk berkaitan dengan literasi finansial). Murid dapat menggunakan rasio (skala, proporsi, dan laju perubahan) dalam penyelesaian masalah.', 'Bilangan', 116, null),
  ('mtk-d-2', 'mtk', 'D', 'SMP/MTs', 'VII–IX', 2, 'Aljabar', 'Mengenali, memprediksi dan menggeneralisasi pola dalam bentuk susunan benda dan bilangan; Menyatakan suatu situasi ke dalam bentuk aljabar; menggunakan sifat-sifat operasi (komutatif, asosiatif, dan distributif) untuk menghasilkan bentuk aljabar yang ekuivalen. Murid dapat memahami relasi dan fungsi (domain, kodomain, range) serta menyajikannya dalam bentuk diagram panah, tabel, himpunan pasangan berurutan, dan grafik; membedakan beberapa fungsi non linear dari fungsi linear secara grafik; menyelesaikan persamaan dan pertidaksamaan linear satu variabel; menyajikan, menganalisis, dan menyelesaikan masalah dengan menggunakan relasi, fungsi dan persamaan linear; serta menyelesaikan sistem persaman linear dua variabel melalui beberapa cara untuk penyelesaian masalah.', 'Aljabar', 116, null),
  ('mtk-d-3', 'mtk', 'D', 'SMP/MTs', 'VII–IX', 3, 'Pengukuran', 'Menentukan keliling, luas, panjang busur, sudut dan luas juring lingkaran, serta menyelesaikan masalah yang terkait; menjelaskan cara untuk menentukan luas permukaan dan volume bangun ruang (prisma, tabung, bola, limas dan kerucut) dan menyelesaikan masalah yang terkait; dan menjelaskan pengaruh perubahan secara proporsional dari bangun datar dan bangun ruang terhadap ukuran panjang, besar sudut, luas, dan/atau volume.', 'Pengukuran', 117, null),
  ('mtk-d-4', 'mtk', 'D', 'SMP/MTs', 'VII–IX', 4, 'Geometri', 'Membuat jaring-jaring bangun ruang (prisma, tabung, limas dan kerucut) dan membuat bangun ruang dari jaring-jaringnya. Murid dapat menggunakan hubungan antar-sudut yang terbentuk oleh dua garis yang berpotongan, dan oleh dua garis sejajar yang dipotong sebuah garis transversal untuk menyelesaikan masalah (termasuk menentukan jumlah besar sudut dalam sebuah segitiga, menentukan besar sudut yang belum diketahui pada sebuah segitiga); menjelaskan sifat-sifat kekongruenan dan kesebangunan pada segitiga dan segiempat, dan menggunakannya untuk menyelesaikan masalah; menunjukkan kebenaran teorema Pythagoras dan menggunakannya dalam menyelesaikan masalah (termasuk pengenalan bilangan irasional dan jarak antara dua titik pada bidang koordinat Kartesius). Murid dapat melakukan transformasi tunggal (refleksi, translasi, rotasi, dan dilatasi) titik, garis, dan bangun datar pada bidang koordinat Kartesius dan menggunakannya untuk menyelesaikan masalah.', 'Geometri', 117, null),
  ('mtk-d-5', 'mtk', 'D', 'SMP/MTs', 'VII–IX', 5, 'Analisis Data dan Peluang', 'Merumuskan pertanyaan, mengumpulkan, menyajikan, dan menganalisis data untuk menjawab pertanyaan dari situasi atau masalah; menggunakan diagram batang dan diagram lingkaran untuk menyajikan dan menginterpretasi data; mengambil sampel yang mewakili suatu populasi untuk mendapatkan data yang terkait dengan diri dan lingkungan mereka; menentukan dan menafsirkan rerata (mean), median, modus, dan jangkauan (range) dari data tersebut untuk menyelesaikan masalah (termasuk membandingkan suatu data terhadap kelompoknya, membandingkan dua kelompok data, memprediksi, membuat keputusan); menyelidiki kemungkinan adanya perubahan pengukuran pusat tersebut akibat perubahan data. Murid dapat menjelaskan dan menggunakan pengertian peluang dan frekuensi relatif untuk menentukan frekuensi harapan satu kejadian pada suatu percobaan sederhana (semua hasil percobaan dapat muncul secara merata).', 'Analisis Data dan Peluang', 118, null),
  ('mtk-e-1', 'mtk', 'E', 'SMA/MA', 'X', 1, 'Bilangan', 'Menggeneralisasi sifat-sifat bilangan berpangkat (termasuk bilangan pangkat pecahan), dan menggunakannya untuk menyelesaikan masalah.', 'Bilangan', 118, null),
  ('mtk-e-2', 'mtk', 'E', 'SMA/MA', 'X', 2, 'Aljabar dan Fungsi', 'Menyelesaikan masalah yang berkaitan dengan sistem pertidaksamaan linear dua variabel; menyelesaikan masalah yang berkaitan dengan persamaan dan fungsi kuadrat (termasuk akar imajiner), serta persamaan eksponensial (berbasis/ bilangan pokok sama) dan fungsi eksponensial.', 'Aljabar dan Fungsi', 118, null),
  ('mtk-e-3', 'mtk', 'E', 'SMA/MA', 'X', 3, 'Geometri', 'Mengaplikasikan perbandingan trigonometri (sinus, cosinus, tangen) dari sudut lancip.', 'Geometri', 119, null),
  ('mtk-e-4', 'mtk', 'E', 'SMA/MA', 'X', 4, 'Analisis Data dan Peluang', 'Merepresentasikan dan menginterpretasi data dengan cara menentukan jangkauan kuartil dan interkuartil; membuat dan menginterpretasi diagram box plot dan menggunakannya untuk membandingkan himpunan data; menentukan dan menggunakan dari box plot, histogram dan dot plot sesuai dengan natur (karakteristik) data dan kebutuhan; menggunakan diagram pencar untuk menyelidiki dan menjelaskan hubungan antara dua variabel numerik/kuantitatif (termasuk salah satunya variabel bebas berupa waktu); serta mengevaluasi laporan statistika di media berdasarkan tampilan, statistika dan representasi data, termasuk yang disajikan dalam bentuk matriks.', 'Analisis Data dan Peluang', 119, null),
  ('mtk-f-1', 'mtk', 'F', 'SMA/MA', 'XI–XII', 1, 'Bilangan', 'Menjelaskan barisan dan deret (aritmetika dan geometri), menerapkannya pada beragam masalah terutama masalah bunga tunggal dan majemuk, memodelkan pinjaman dan investasi dengan bunga majemuk dan anuitas, serta menyelidiki (secara numerik atau grafis) pengaruh masing-masing parameter (suku bunga, periode pembayaran) dalam model tersebut.', 'Bilangan', 119, null),
  ('mtk-f-2', 'mtk', 'F', 'SMA/MA', 'XI–XII', 2, 'Aljabar dan Fungsi', 'Menentukan fungsi invers, komposisi fungsi, dan transformasi fungsi untuk memodelkan situasi dunia nyata menggunakan fungsi yang sesuai (linear, kuadrat, eksponensial).', 'Aljabar dan Fungsi', 120, null),
  ('mtk-f-3', 'mtk', 'F', 'SMA/MA', 'XI–XII', 3, 'Geometri', 'Menerapkan, mengidentifikasi dan menjelaskan hubungan antara unsur-unsur lingkaran untuk menyelesaikan masalah.', 'Geometri', 120, null),
  ('mtk-f-4', 'mtk', 'F', 'SMA/MA', 'XI–XII', 4, 'Analisis Data dan Peluang', 'Melakukan proses penyelidikan statistika untuk mengidentifikasi dan menjelaskan asosiasi antara dua variabel kategorikal (kualitatif) dan antara dua variabel numerikal (kuantitatif); memperkirakan model linear terbaik (best fit linear) pada data numerikal (kuantitatif); membedakan hubungan asosiasi dan sebab-akibat; menjelaskan peluang dan menentukan frekuensi harapan dari kejadian majemuk; menyelidiki konsep dari kejadian saling bebas dan saling lepas, dan menentukan peluangnya; serta memahami konsep peluang bersyarat dan kejadian yang saling bebas menggunakan konsep permutasi dan kombinasi.', 'Analisis Data dan Peluang', 120, null),
  ('mtk-tl-f-1', 'mtk-tl', 'F', 'SMA/MA', 'XI–XII', 1, 'Aljabar dan Fungsi', 'Melakukan operasi aritmetika pada polinomial (suku banyak), menentukan faktor polinomial, dan menggunakan identitas polinomial untuk menyelesaikan masalah; melakukan operasi aljabar pada matriks dan menerapkannya dalam transformasi geometri; menyatakan fungsi trigonometri menggunakan lingkaran satuan, memodelkan fenomena periodik dengan fungsi trigonometri, dan membuktikan serta menerapkan identitas trigonometri dan aturan cosinus dan sinus; mengenal berbagai fungsi (termasuk fungsi rasional, fungsi akar, fungsi eksponensial, fungsi logaritma, fungsi nilai mutlak, fungsi tangga dan fungsi piecewise) dan menggunakannya untuk memodelkan berbagai fenomena.', 'Aljabar dan Fungsi', 125, null),
  ('mtk-tl-f-2', 'mtk-tl', 'F', 'SMA/MA', 'XI–XII', 2, 'Geometri', 'Menyatakan vektor pada bidang datar, dan melakukan operasi aljabar pada vektor; melakukan pembuktian geometris menggunakan vektor; serta menyatakan sifat-sifat geometri dari persamaan lingkaran, elips dan persamaan garis singgung.', 'Geometri', 125, null),
  ('mtk-tl-f-3', 'mtk-tl', 'F', 'SMA/MA', 'XI–XII', 3, 'Analisis Data dan Peluang', 'Memahami variabel acak diskrit (distribusi binomial) dan fungsi peluang (distribusi normal), dan menggunakannya dalam memodelkan data; menginterpretasi parameter distribusi data secara statistik, menghitung nilai harapan distribusi binomial dan normal, dan menggunakannya dalam penyelesaian masalah.', 'Analisis Data dan Peluang', 125, null),
  ('mtk-tl-f-4', 'mtk-tl', 'F', 'SMA/MA', 'XI–XII', 4, 'Kalkulus', 'Memahami laju perubahan dan laju perubahan rata-rata, serta laju perubahan sesaat sebagai konsep kunci derivatif (turunan), baik secara geometris maupun aljabar; menentukan turunan dari fungsi polinomial, eksponensial, dan trigonometri, dan menerapkan derivatif untuk membuat sketsa kurva, menghitung gradien dan menentukan persamaan garis singgung, menentukan kecepatan sesaat dan menyelesaikan soal optimasi; memahami integral, baik sebagai proses yang merupakan kebalikan dari derivatif dan juga sebagai cara menghitung luas; serta memahami teorema dasar kalkulus sebagai penghubung antara derivatif dan integral.', 'Kalkulus', 126, null),
  ('bing-b-1', 'bing', 'B', 'SD/MI', 'III–IV', 1, 'Menyimak-Berbicara (Listening-Speaking)', 'Memahami dan merespon teks lisan atau teks multimodal sederhana tentang kehidupan sehari-hari baik secara verbal atau non-verbal sesuai konteks. (understand and respond to simple oral or multimodal texts about everyday life verbally or non-verbally in line with its context)', 'Menyimak - Berbicara (Listening - Speaking)', 133, null),
  ('bing-b-2', 'bing', 'B', 'SD/MI', 'III–IV', 2, 'Membaca-Memirsa (Reading-Viewing)', 'Memahami teks tulis pendek sederhana atau teks multimodal tentang kehidupan sehari-hari dan meresponsnya secara verbal atau non-verbal sesuai konteks. (Understand simple short texts or multimodal texts about everyday life and respond to them verbally or non-verbally in line with its context)', 'Membaca - Memirsa (Reading - Viewing)', 134, null),
  ('bing-b-3', 'bing', 'B', 'SD/MI', 'III–IV', 3, 'Menulis-Mempresentasikan (Writing-Presenting)', 'Mengomunikasikan gagasan tentang topik sehari-hari dalam teks tulis pendek atau teks multimodal sesuai konteks. (Communicate their ideas on everyday life topics in simple written or multimodal texts in line with its context)', 'Menulis - Mempresentasikan (Writing - Presenting)', 134, null),
  ('bing-c-1', 'bing', 'C', 'SD/MI', 'V–VI', 1, 'Menyimak-Berbicara (Listening-Speaking)', 'Memahami alur informasi teks secara keseluruhan dan merespon teks lisan atau teks multimodal sederhana tentang topik sehari-hari secara lisan dengan kalimat pendek dan sederhana sesuai konteks. (Understand the entire flow of information and respond to simple oral or multimodal texts about everyday topics using short and simple sentences verbally in line with its context)', 'Menyimak - Berbicara (Listening - Writing)', 134, null),
  ('bing-c-2', 'bing', 'C', 'SD/MI', 'V–VI', 2, 'Membaca-Memirsa (Reading-Viewing)', 'Memahami alur informasi secara keseluruhan, gagasan utama dan informasi rinci dari beragam teks pendek atau teks multimodal tentang topik sehari-hari dan meresponnya sesuai konteks. (Understand the entire flow of information, main ideas and details from a variety of short texts or multimodal texts about everyday topics and respond in line with its context)', 'Membaca - Memirsa (Reading - Viewing)', 134, null),
  ('bing-c-3', 'bing', 'C', 'SD/MI', 'V–VI', 3, 'Menulis-Mempresentasikan (Writing-Presenting)', 'Mengomunikasikan ide dan pengalamannya melalui berbagai jenis teks tulis sederhana atau teks multimodal tentang topik sehari-hari sesuai konteks. (Communicate their ideas and experiences through various types of simple written texts or multimodal texts about everyday topics in line with its context)', 'Menulis - Mempresentasikan (Writing - Presenting)', 135, null),
  ('bing-d-1', 'bing', 'D', 'SMP/MTs', 'VII–IX', 1, 'Menyimak-Berbicara (Listening-Speaking)', 'Memahami alur informasi secara keseluruhan, gagasan utama dan informasi rinci dari teks lisan tentang topik sehari-hari atau yang sesuai dengan minat; menggunakan bahasa Inggris untuk mengungkapkan gagasan dan pengalaman dalam berbagai jenis teks secara lisan tentang topik yang dibahas dengan menggunakan kalimat sederhana dan majemuk baik formal maupun informal sesuai konteks. (Understand the entire flow of information, main ideas and details of oral texts about everyday topics or topics of interest; using English to express ideas and experiences in various types of texts orally about the topics discussed using simple and compound sentences, both formally and informally in line with its context)', 'Menyimak - Berbicara (Listening - Speaking)', 135, null),
  ('bing-d-2', 'bing', 'D', 'SMP/MTs', 'VII–IX', 2, 'Membaca-Memirsa (Reading-Viewing)', 'Memahami alur informasi, informasi tersurat dan tersirat dari berbagai jenis teks tertulis atau teks multimodal tentang topik sehari-hari atau yang sesuai dengan minat dan meresponnya sesuai konteks. (Understand the entire flow of information, explicit and implicit information from various types of written or multimodal texts about everyday topics or topics of interest and respond in line with its context)', 'Membaca - Memirsa (Reading - Viewing)', 135, null),
  ('bing-d-3', 'bing', 'D', 'SMP/MTs', 'VII–IX', 3, 'Menulis-Mempresentasikan (Writing-Presenting)', 'Mengomunikasikan gagasan dan pengalaman mereka dalam berbagai jenis teks secara tertulis atau teks multimodal tentang topik sehari-hari atau yang sesuai dengan minat dengan mulai menggunakan kalimat sederhana dan majemuk dengan struktur teks dan unsur kebahasaan yang tepat; mengungkapkan pendapat dan mempertahankan argumen tentang suatu isu terkait topik sehari-hari atau yang sesuai dengan minat. (Communicate their ideas and experiences in various types of texts, in written or multimodal texts, about everyday topics or topics of interest, by starting to use simple and compound sentences with appropriate text structures and language features; express their opinions and defend their arguments on issues related to daily topics or topics of interests)', 'Menulis-Mempresentasikan (Writing - Presenting)', 136, null),
  ('bing-e-1', 'bing', 'E', 'SMA/MA', 'X', 1, 'Menyimak-Berbicara (Listening-Speaking)', 'Memahami alur informasi secara keseluruhan, gagasan utama dan detail dalam teks lisan fiksi dan non fiksi mengenai berbagai macam topik yang relevan dengan topik sehari-hari atau isu terkini; menggunakan bahasa Inggris untuk mengungkapkan pendapat dan mempertahankan argumen tentang topik yang dibahas. (Understand the entire flow of information, the main idea and details in fiction and nonfiction spoken texts about various topics relevant to everyday topics or current issues; using English to express their opinions and defend their arguments about the topics discussed)', 'Menyimak - Berbicara (Listening - Speaking)', 136, null),
  ('bing-e-2', 'bing', 'E', 'SMA/MA', 'X', 2, 'Membaca-Memirsa (Reading-Viewing)', 'Memahami alur informasi secara keseluruhan, menganalisis dan menyimpulkan informasi tersurat dan tersirat dari berbagai jenis teks fiksi dan non fiksi tertulis atau teks multimodal tentang topik sehari-hari atau isu terkini. (Understand the entire flow of information, analyze and infer explicit and implicit information in fiction and nonfiction from written and multimodal texts about everyday topics or current issues)', 'Membaca - Memirsa (Reading - Viewing)', 137, null),
  ('bing-e-3', 'bing', 'E', 'SMA/MA', 'X', 3, 'Menulis-Mempresentasikan (Writing-Presenting)', 'Mengomunikasikan gagasan dan pengalaman mereka secara tertulis atau multimodal dalam berbagai jenis teks fiksi dan nonfiksi dengan menggunakan berbagai media presentasi (cetak atau digital) untuk mencapai tujuan tertentu dengan struktur teks dan unsur kebahasaan yang tepat; mengungkapkan pendapat dan mempertahankan argumen tentang topik sehari-hari atau isu terkini. (Communicate their ideas and experiences in written or multimodal texts in fiction and nonfiction texts using different media of presentation (print and digital) to achieve specific goals with appropriate text structures and language features; express their opinions and defend their arguments about everyday topics or current issues)', 'Menulis-Mempresentasikan (Writing - Presenting)', 137, null),
  ('bing-f-1', 'bing', 'F', 'SMA/MA', 'XI–XII', 1, 'Menyimak-Berbicara (Listening-Speaking)', 'Memahami alur informasi secara keseluruhan dari teks lisan fiksi dan non fiksi tentang isu terkini atau topik terkait mata pelajaran lain; menggunakan bahasa Inggris untuk mengungkapkan pendapat dan mempertahankan argumen tentang topik yang dibahas. (Understand the entire flow of information in fiction and nonfiction spoken texts about current issues or topics related to other subjects; students use English to express their opinions and defend their arguments about the topics discussed)', 'Menyimak-Berbicara (Listening-Speaking)', 138, null),
  ('bing-f-2', 'bing', 'F', 'SMA/MA', 'XI–XII', 2, 'Membaca-Memirsa (Reading-Viewing)', 'Mengevaluasi informasi tersurat dan tersirat dari berbagai jenis teks fiksi dan non fiksi tertulis atau teks multimodal tentang isu terkini atau topik yang terkait mata pelajaran lain. (Evaluate explicit and implicit information in fiction and nonfiction from written and multimodal texts about current issues or topics related to other subjects)', 'Membaca - Memirsa (Reading - Viewing)', 138, null),
  ('bing-f-3', 'bing', 'F', 'SMA/MA', 'XI–XII', 3, 'Menulis-Mempresentasikan (Writing-Presenting)', 'Mengomunikasikan gagasan atau pengalaman secara tertulis atau multimodal dalam berbagai jenis teks fiksi dan nonfiksi dengan struktur teks dan unsur kebahasaan yang tepat dan kompleks dengan menggunakan berbagai media presentasi (cetak dan digital) untuk mencapai tujuan yang berbeda-beda; menunjukkan strategi koreksi dalam kaidah menulis baik dengan bantuan pendidik maupun mandiri; mengungkapkan pendapat dan mempertahankan argumen tentang isu terkini atau topik yang terkait mata pelajaran lain. (Communicate ideas or experiences in written or multimodal texts in fiction and nonfiction texts with appropriate and complex text structures and language features, using different media of presentation (print and digital) to achieve different purposes; demonstrate correction strategies in writing conventions with the help of a teacher or independently; express their opinions and defend their arguments on current issues or topics related to other subjects)', 'Menulis-Mempresentasikan (Writing-Presenting)', 138, null),
  ('bing-tl-f-1', 'bing-tl', 'F', 'SMA/MA', 'XI–XII', 1, 'Menyimak-Berbicara (Listening-Speaking)', 'Memahami alur cerita atau informasi dari teks narasi, eksposisi, dan diskusi tentang isu terkini atau topik terkait mata pelajaran lain secara lisan atau multimodal; menggunakan bahasa Inggris untuk mengungkapkan pendapat dan mempertahankan argumen tentang topik yang dibahas. (Understand the storyline or information from narrative, exposition, and discussion texts on current issues or topics related to other subjects in spoken or multimodal texts; using English to express their opinions and defend their arguments about the topics being discussed)', 'Menyimak - Berbicara (Listening - Speaking)', 145, null),
  ('bing-tl-f-2', 'bing-tl', 'F', 'SMA/MA', 'XI–XII', 2, 'Membaca-Memirsa (Reading-Viewing)', 'Mengevaluasi dan merefleksi informasi tersurat dan tersirat dari teks narasi, eksposisi dan diskusi tentang isu terkini baik nasional maupun global, atau topik yang terkait mata pelajaran lain secara tertulis atau multimodal. (Evaluate and reflect on explicit and implicit information from narrative, exposition, and discussion on current issues, both national and global, or topics related to other subjects in written or multimodal texts)', 'Membaca-Memirsa (Reading-Viewing)', 146, null),
  ('bing-tl-f-3', 'bing-tl', 'F', 'SMA/MA', 'XI–XII', 3, 'Menulis-Mempresentasikan (Writing-Presenting)', 'Mengomunikasikan gagasan atau pengalaman secara tertulis atau multimodal dalam teks narasi, eksposisi, dan diskusi tentang berbagai topik dengan struktur teks dan unsur kebahasaan yang tepat, jelas, dan detail dengan menggunakan berbagai media presentasi (cetak atau digital); menulis cerita pendek, pendapat atau pandangan tentang suatu topik atau isu dengan mengungkapkan argumen yang didukung dengan data dan fakta, atau membahas suatu isu dengan menjelaskan manfaat dan kelemahan atau argumen yang mendukung dan menentang tentang suatu isu terkini yang kontroversial. (Communicate ideas or experiences in written or multimodal texts in narrative, exposition, and discussion texts on various topics with clear and detailed text structure and language features using different media of presentation (print or digital); write short stories, their opinions or viewpoints about a topic or an issue by using arguments supported with data and facts, or discuss an issue by explaining the advantages and disadvantages or arguments for and against controversial current issues)', 'Menulis-Mempresentasikan (Writing-Presenting)', 146, null),
  ('ipas-b-1', 'ipas', 'B', 'SD/MI', 'III–IV', 1, 'Pemahaman IPAS', 'Menjelaskan bentuk dan fungsi pancaindra; menganalisis siklus hidup makhluk hidup dan upaya pelestariannya; menghasilkan solusi untuk masalah yang berkaitan dengan pelestarian sumber daya alam sebagai upaya mitigasi perubahan iklim; menyimpulkan proses perubahan wujud zat; menjelaskan sumber dan bentuk energi, serta proses perubahan bentuk energi dalam kehidupan sehari-hari; membedakan jenis gaya dan pengaruhnya terhadap arah, gerak, dan bentuk benda; menjelaskan peran, tugas, dan tanggung jawab serta interaksi sosial yang terjadi di sekitar tempat tinggal dan sekolah; mengenali letak kabupaten/kota dan provinsi tempat tinggalnya dengan menggunakan peta konvensional/digital; mengklasifikasikan ragam bentang alam dan keterkaitannya dengan profesi masyarakat, ragam budaya serta upaya untuk melestarikannya; menganalisis sejarah masyarakat di lingkungan tempat tinggal; menjelaskan nilai mata uang dan fungsinya, serta cara mengelola keuangan secara bijak.', 'Pemahaman IPAS', 150, null),
  ('ipas-b-2', 'ipas', 'B', 'SD/MI', 'III–IV', 2, 'Keterampilan Proses', 'Mampu menerapkan keterampilan proses yang meliputi:
• Mengamati: Murid mengamati fenomena dan peristiwa secara sederhana dan dapat mencatat hasil pengamatannya.
• Mempertanyakan dan Memprediksi: Secara mandiri, murid mengajukan pertanyaan tentang hal-hal yang ingin diketahui saat melakukan pengamatan dan membuat prediksi berdasarkan pengetahuan yang dimiliki sebelumnya.
• Merencanakan dan Melakukan Penyelidikan: Dengan panduan pendidik, murid membuat rencana dan melakukan langkah-langkah operasional untuk menjawab pertanyaan yang diajukan. Murid melakukan observasi menggunakan alat bantu pengukuran sederhana.
• Memproses, Menganalisis Data dan Informasi: Dengan panduan pendidik, murid mengorganisasikan data dalam bentuk turus dan diagram gambar untuk menyajikan dan mengidentifikasi pola. Murid membandingkan antara hasil pengamatan dengan prediksi dan memberikan penjelasan.
• Mengevaluasi dan Refleksi: Murid melakukan refleksi terhadap penyelidikan yang sudah dilakukan.
• Mengomunikasikan Hasil: Murid mengomunikasikan hasil penyelidikan secara lisan dan tertulis dalam berbagai media.', 'Keterampilan Proses', 150, null),
  ('ipas-c-1', 'ipas', 'C', 'SD/MI', 'V–VI', 1, 'Pemahaman IPAS', 'Merefleksikan sistem organ tubuh manusia yang dikaitkan dengan cara menjaga kesehatan tubuhnya; menganalisis hubungan antar komponen biotik dan abiotik, serta pengaruhnya terhadap ekosistem; menjelaskan fenomena gelombang bunyi dan cahaya dalam kehidupan sehari-hari; menghasilkan upaya penghematan energi, serta pemanfaatan sumber energi alternatif dari sumber daya yang ada di sekitarnya sebagai upaya mitigasi perubahan iklim; menjelaskan sistem tata surya, serta kaitannya dengan rotasi dan revolusi bumi; menjelaskan letak dan kondisi geografis negara Indonesia dengan menggunakan peta konvensional/digital; meninjau sejarah perjuangan para pahlawan di lingkungan sekitar tempat tinggalnya; menemukan keragaman budaya nasional dalam konteks kebhinekaan berdasarkan pemahaman terhadap nilai-nilai kearifan lokal yang berlaku di wilayah tempat tinggal; serta menerapkan kegiatan ekonomi masyarakat di lingkungan sekitar.', 'Pemahaman IPAS', 151, null),
  ('ipas-c-2', 'ipas', 'C', 'SD/MI', 'V–VI', 2, 'Keterampilan Proses', 'Mampu menerapkan keterampilan proses yang meliputi:
• Mengamati: Murid mengamati fenomena dan peristiwa secara sederhana, mencatat hasil pengamatannya, serta mencari persamaan dan perbedaannya.
• Mempertanyakan dan Memprediksi: Dengan panduan pendidik, murid mengidentifikasi pertanyaan yang dapat diselidiki secara ilmiah dan membuat prediksinya.
• Merencanakan dan Melakukan Penyelidikan: Secara mandiri, murid merencanakan dan melakukan langkah-langkah operasional untuk menjawab pertanyaan yang diajukan. Murid melakukan observasi menggunakan alat bantu pengukuran sederhana.
• Memproses serta Menganalisis Data dan Informasi: Murid mengolah data dalam bentuk tabel dan grafik, serta menjelaskan hasil pengamatan dan pola atau hubungan pada data. Murid membandingkan data dengan prediksi dan memberikan alasan berdasarkan bukti.
• Mengevaluasi dan Refleksi: Melakukan refleksi dan memberikan saran perbaikan terhadap penyelidikan yang sudah dilakukan.
• Mengomunikasikan Hasil: Murid mengomunikasikan hasil penyelidikan secara utuh yang ditunjang dengan argumen dalam berbagai media.', 'Keterampilan Proses', 152, null),
  ('ipa-d-1', 'ipa', 'D', 'SMP/MTs', 'VII–IX', 1, 'Pemahaman IPA', 'Menelaah hasil identifikasi makhluk hidup sesuai dengan karakteristiknya; menganalisis klasifikasi, sifat, dan perubahan materi; menganalisis sistem organisasi kehidupan, fungsi, serta kelainan atau gangguan yang muncul pada sistem organ; menganalisis interaksi antar makhluk hidup dan lingkungannya dalam merancang upaya-upaya untuk mencegah dan mengatasi perubahan iklim; menganalisis pewarisan sifat; membuat bioteknologi konvensional di lingkungan sekitarnya; menerapkan pengukuran terhadap aspek fisis dalam kehidupan sehari-hari; menganalisis ragam gerak, gaya, dan tekanan; menganalisis hubungan usaha dan energi; menganalisis pengaruh kalor dan perpindahannya terhadap perubahan suhu; menganalisis gelombang dan pemanfaatannya dalam kehidupan sehari-hari; menganalisis gejala kemagnetan dan kelistrikan untuk menyelesaikan tantangan yang dihadapi dalam kehidupan sehari-hari termasuk pemanfaatan sumber energi listrik ramah lingkungan; menganalisis posisi relatif bumi-bulan-matahari dalam sistem tata surya untuk menjelaskan fenomena alam dan perubahan iklim; serta mengevaluasi keputusan yang tepat untuk menghindari zat aditif dan adiktif yang membahayakan dirinya dan lingkungan.', 'Pemahaman IPA', 157, null),
  ('ipa-d-2', 'ipa', 'D', 'SMP/MTs', 'VII–IX', 2, 'Keterampilan Proses', 'Mampu menerapkan keterampilan proses yang meliputi:
• Mengamati: Melakukan pengamatan terhadap fenomena dan peristiwa di sekitarnya dan mencatat hasil pengamatannya dengan memperhatikan karakteristik objek yang diamati.
• Mempertanyakan dan Memprediksi: Mengidentifikasi pertanyaan yang dapat diselidiki secara ilmiah dan membuat prediksinya.
• Merencanakan dan Melakukan Penyelidikan: Merencanakan dan melakukan langkah-langkah operasional untuk menjawab pertanyaan; murid menggunakan alat bantu pengukuran untuk mendapatkan data yang akurat dan memahami adanya potensi kekeliruan dalam penyelidikan.
• Memproses, Menganalisis Data dan Informasi: Mengolah data dalam bentuk tabel, grafik, dan model serta menjelaskan hasil pengamatan dan pola atau hubungan pada data; murid mengumpulkan data dari penyelidikan yang dilakukannya, serta menggunakan pemahaman sains untuk mengidentifikasi hubungan dan menarik kesimpulan berdasarkan bukti.
• Mengevaluasi dan Refleksi: Mengidentifikasi sumber ketidakpastian dan kemungkinan penjelasan alternatif dalam rangka mengevaluasi kesimpulan, serta menjelaskan cara spesifik untuk meningkatkan kualitas data.
• Mengomunikasikan Hasil: Mengomunikasikan hasil penyelidikan secara sistematis dan utuh yang ditunjang dengan argumen dan bahasa yang sesuai konteks penyelidikan.', 'Keterampilan Proses', 158, null),
  ('ipa-e-1', 'ipa', 'E', 'SMA/MA', 'X', 1, 'Pemahaman IPA', 'Menerapkan prinsip klasifikasi dan strategi pelestarian keanekaragaman hayati; mendeskripsikan peranan virus, bakteri, dan jamur dalam kehidupan; menganalisis interaksi antar komponen ekosistem dan pengaruhnya terhadap keseimbangan ekosistem; menggunakan sistem pengukuran dalam kerja ilmiah; menganalisis gerak dua dimensi; menganalisis pemanfaatan energi alternatif untuk mengatasi permasalahan ketersediaan energi; menganalisis partikel penyusun materi dan menerapkan konsep stoikiometri dalam berbagai aspek kuantitatif reaksi kimia; dan menerapkan konsep IPA untuk mengatasi permasalahan berkaitan dengan perubahan iklim.', 'Pemahaman IPA', 159, null),
  ('ipa-e-2', 'ipa', 'E', 'SMA/MA', 'X', 2, 'Keterampilan Proses', 'Mampu menerapkan keterampilan proses yang meliputi:
• Mengamati: Melakukan pengamatan terhadap fenomena dan peristiwa di sekitarnya dan mencatat hasil pengamatannya dengan memperhatikan karakteristik objek yang diamati.
• Mempertanyakan dan Memprediksi: Mengidentifikasi pertanyaan yang dapat diselidiki secara ilmiah dan membuat prediksinya.
• Merencanakan dan Melakukan Penyelidikan: Merencanakan dan melakukan langkah-langkah operasional untuk menjawab pertanyaan; murid menggunakan alat bantu pengukuran untuk mendapatkan data yang akurat dan memahami adanya potensi kekeliruan dalam penyelidikan.
• Memproses, Menganalisis Data dan Informasi: Mengolah data dalam bentuk tabel, grafik, dan model serta menjelaskan hasil pengamatan dan pola atau hubungan pada data; murid mengumpulkan data dari penyelidikan yang dilakukannya, serta menggunakan pemahaman sains untuk mengidentifikasi hubungan dan menarik kesimpulan berdasarkan bukti.
• Mengevaluasi dan Refleksi: Mengidentifikasi sumber ketidakpastian dan kemungkinan penjelasan alternatif dalam rangka mengevaluasi kesimpulan, serta menjelaskan cara spesifik untuk meningkatkan kualitas data.
• Mengomunikasikan Hasil: Mengomunikasikan hasil penyelidikan secara sistematis dan utuh yang ditunjang dengan argumen dan bahasa yang sesuai konteks penyelidikan.', 'Keterampilan Proses', 159, null),
  ('fis-f-1', 'fis', 'F', 'SMA/MA', 'XI–XII', 1, 'Pemahaman Fisika', 'Menganalisis hubungan gerak dan gaya serta pemanfaatannya untuk menjelaskan fenomena alam, desain, atau rekayasa struktur; membuat karya yang menunjukkan penerapan hukum fluida dalam kehidupan sehari-hari; menganalisis konsep kalor dan termodinamika serta penerapannya untuk mengidentifikasi fenomena perubahan iklim; menganalisis gejala gelombang dan penerapannya dalam kehidupan sehari-hari; mengevaluasi rangkaian listrik; menganalisis fenomena elektromagnetik; menganalisis teori dasar fisika modern dan pengaruhnya terhadap perkembangan teknologi; serta menerapkan teori dasar digital dalam kehidupan sehari-hari.', 'Pemahaman Fisika', 164, null),
  ('fis-f-2', 'fis', 'F', 'SMA/MA', 'XI–XII', 2, 'Keterampilan Proses', 'Menerapkan keterampilan proses yang mencakup:
• Mengamati: Mengamati fenomena ilmiah dalam kehidupan sehari-hari maupun di laboratorium dan mencatat hasil pengamatannya dengan memperhatikan detail dari objek yang diamati untuk memunculkan pertanyaan yang akan diselidiki.
• Mempertanyakan dan Memprediksi: Merumuskan pertanyaan ilmiah tentang hubungan antar variabel dan hipotesis yang dapat diselidiki secara ilmiah.
• Merencanakan dan Melakukan Penyelidikan: Merencanakan dan memilih metode yang sesuai serta mengendalikan variabel berdasarkan referensi untuk mengumpulkan data yang dapat dipercaya; memilih dan menggunakan alat dan bahan, termasuk penggunaan teknologi digital yang sesuai untuk mengumpulkan serta mencatat data secara sistematis dan akurat.
• Memproses, Menganalisis Data dan Informasi: Menafsirkan informasi yang diperoleh dengan jujur dan bertanggung jawab; menggunakan berbagai metode untuk menganalisa pola dan kecenderungan pada data; mendeskripsikan hubungan antar variabel serta mengidentifikasi inkonsistensi yang terjadi; menggunakan data dan rujukan untuk menarik kesimpulan yang konsisten dengan hasil penyelidikan.
• Mengevaluasi dan Refleksi: Mengidentifikasi sumber ketidakpastian dan kemungkinan penjelasan alternatif dalam rangka mengevaluasi kesimpulan serta menjelaskan cara spesifik untuk meningkatkan kualitas data; menganalisis validitas informasi dari sumber primer dan sekunder serta mengevaluasi pendekatan yang digunakan untuk menyelesaikan masalah dalam penyelidikan.
• Mengomunikasikan Hasil: Mengomunikasikan hasil penyelidikan secara sistematis dan utuh ditunjang dengan argumen ilmiah dan terbuka terhadap pendapat yang lebih relevan.', 'Keterampilan Proses', 165, null),
  ('kim-f-1', 'kim', 'F', 'SMA/MA', 'XI–XII', 1, 'Pemahaman Kimia', 'Menganalisis hubungan struktur atom dengan sistem periodik unsur; membandingkan jenis ikatan kimia serta kaitannya dengan bentuk molekul dan gaya intermolekuler dalam memprediksi sifat fisik materi; mengaitkan perubahan entalpi standar dari suatu reaksi kimia dengan sumber energi yang ada di lingkungan sekitar; menganalisis faktor-faktor yang mempengaruhi laju reaksi; menganalisis kesetimbangan kimia dan penerapannya; menjelaskan daya hantar listrik dan sifat koligatif larutan; menjelaskan sel elektrokimia dalam kehidupan sehari-hari; dan menjelaskan senyawa karbon dan makromolekul.', 'Pemahaman Kimia', 170, null),
  ('kim-f-2', 'kim', 'F', 'SMA/MA', 'XI–XII', 2, 'Keterampilan Proses', 'Menerapkan keterampilan proses yang mencakup:
• Mengamati: Mengamati fenomena ilmiah dalam kehidupan sehari-hari maupun di laboratorium dan mencatat hasil pengamatannya dengan memperhatikan detail dari objek yang diamati untuk memunculkan pertanyaan yang akan diselidiki.
